COMMENT ON COLUMN "param"."if97_saturation__basic"."n8" IS 'Constant term of C.';
COMMENT ON COLUMN "param"."if97_saturation__basic"."n9" IS 'Numerator of the pole term of theta.';
COMMENT ON COLUMN "param"."if97_saturation__basic"."n10" IS 'Reduced temperature of the pole of theta.';

CREATE TABLE "prov"."import_record" (
    "id" uuid NOT NULL,
    "artifact" uuid NOT NULL,
    "locator" text NOT NULL,
    "reader" text NOT NULL,
    "reader_version" text NOT NULL,
    CONSTRAINT "import_record__pk" PRIMARY KEY ("id"),
    CONSTRAINT "import_record__identity" UNIQUE ("artifact", "locator"),
    CONSTRAINT "import_record__ck__locator_nonempty" CHECK ("locator" <> '')
);
COMMENT ON TABLE "prov"."import_record" IS 'The statement that an artifact, at a locator, asserts something. It is the link from a canonical record back to the exact source bytes.';
COMMENT ON COLUMN "prov"."import_record"."id" IS 'Deterministic identifier of the import_record instance.';
COMMENT ON COLUMN "prov"."import_record"."artifact" IS 'The file the assertion was read from.';
COMMENT ON COLUMN "prov"."import_record"."locator" IS 'Position within the file: a row key, JSON pointer, line range or element path.';
COMMENT ON COLUMN "prov"."import_record"."reader" IS 'The reader that produced the source-faithful row.';
COMMENT ON COLUMN "prov"."import_record"."reader_version" IS 'Version of that reader.';

CREATE TABLE "tk"."isotope" (
    "id" uuid NOT NULL,
    "mass_number" bigint NOT NULL,
    "atomic_mass" "meta"."molar_mass",
    "symbol" text,
    CONSTRAINT "isotope__pk" PRIMARY KEY ("id"),
    CONSTRAINT "isotope__ck__mass_number_positive" CHECK ("mass_number" > 0)
);
COMMENT ON TABLE "tk"."isotope" IS 'A nuclide of an element counted apart from it, such as deuterium, tritium or oxygen-18. An isotope is not an element: atomic numbers identify elements and one element has several isotopes. A reaction''s balance of an element counts the isotopes of that element too.';
COMMENT ON COLUMN "tk"."isotope"."id" IS 'Deterministic identifier of the isotope instance.';
COMMENT ON COLUMN "tk"."isotope"."mass_number" IS 'The mass number: protons plus neutrons.';
COMMENT ON COLUMN "tk"."isotope"."atomic_mass" IS 'The atomic mass of the nuclide, where the source states it.';
COMMENT ON COLUMN "tk"."isotope"."symbol" IS 'The symbol the source uses for the nuclide where it has one of its own, such as D or T.';

CREATE TABLE "prov"."level_of_theory" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "method" text NOT NULL,
    "basis" text,
    "auxiliary_basis" text,
    "cabs" text,
    "software" uuid,
    "solvent" text,
    "solvation_method" text,
    "arguments" text,
    "frequency_level" uuid,
    "energy_level" uuid,
    CONSTRAINT "level_of_theory__pk" PRIMARY KEY ("id"),
    CONSTRAINT "level_of_theory__identity" UNIQUE ("key"),
    CONSTRAINT "level_of_theory__ck__key_nonempty" CHECK ("key" <> '')
);
COMMENT ON TABLE "prov"."level_of_theory" IS 'The level of theory of a computed value: the method, basis set, auxiliary basis, solvent model and software release a quantum-chemistry calculation used, or, for a composite, the levels of its frequency and its energy calculation. The key is a canonical rendering of these fields that the mapping builds, so two computations at one level share one row.';
COMMENT ON COLUMN "prov"."level_of_theory"."id" IS 'Deterministic identifier of the level_of_theory instance.';
COMMENT ON COLUMN "prov"."level_of_theory"."key" IS 'The canonical rendering of the fields below.';
COMMENT ON COLUMN "prov"."level_of_theory"."method" IS 'The method or functional, as the source names it.';
COMMENT ON COLUMN "prov"."level_of_theory"."basis" IS 'The basis set.';
COMMENT ON COLUMN "prov"."level_of_theory"."auxiliary_basis" IS 'The auxiliary basis set, for density fitting.';
COMMENT ON COLUMN "prov"."level_of_theory"."cabs" IS 'The complementary auxiliary basis set of an explicitly correlated method.';
COMMENT ON COLUMN "prov"."level_of_theory"."software" IS 'The release of the program that ran the calculation.';
COMMENT ON COLUMN "prov"."level_of_theory"."solvent" IS 'The solvent, for a calculation in solution.';
COMMENT ON COLUMN "prov"."level_of_theory"."solvation_method" IS 'The solvent model.';
COMMENT ON COLUMN "prov"."level_of_theory"."arguments" IS 'The program arguments as the source writes them. Retained; nothing branches on it.';
COMMENT ON COLUMN "prov"."level_of_theory"."frequency_level" IS 'For a composite level, the level of its frequency calculation.';
COMMENT ON COLUMN "prov"."level_of_theory"."energy_level" IS 'For a composite level, the level of its energy calculation.';

CREATE TABLE "prov"."licence" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "spdx" "meta"."id_spdx",
    "title" text NOT NULL,
    CONSTRAINT "licence__pk" PRIMARY KEY ("id"),
    CONSTRAINT "licence__identity" UNIQUE ("key")
);
COMMENT ON TABLE "prov"."licence" IS 'A named set of terms.';
COMMENT ON COLUMN "prov"."licence"."id" IS 'Deterministic identifier of the licence instance.';
COMMENT ON COLUMN "prov"."licence"."key" IS 'Stable key.';
COMMENT ON COLUMN "prov"."licence"."spdx" IS 'SPDX identifier where one exists.';
COMMENT ON COLUMN "prov"."licence"."title" IS 'Name of the terms.';

CREATE TABLE "qual"."mapping_coverage" (
    "id" uuid NOT NULL,
    "manifest_id" text NOT NULL,
    "source_table" text NOT NULL,
    "state" "meta"."row_state" NOT NULL,
    "rows" bigint NOT NULL,
    CONSTRAINT "mapping_coverage__pk" PRIMARY KEY ("id"),
    CONSTRAINT "mapping_coverage__identity" UNIQUE ("manifest_id", "source_table", "state"),
    CONSTRAINT "mapping_coverage__ck__rows_nonnegative" CHECK ("rows" >= 0)
);
COMMENT ON TABLE "qual"."mapping_coverage" IS 'How many rows of a source-faithful table ended in each state in one build.';
COMMENT ON COLUMN "qual"."mapping_coverage"."id" IS 'Deterministic identifier of the mapping_coverage instance.';
COMMENT ON COLUMN "qual"."mapping_coverage"."manifest_id" IS 'The source.';
COMMENT ON COLUMN "qual"."mapping_coverage"."source_table" IS 'The source-faithful table.';
COMMENT ON COLUMN "qual"."mapping_coverage"."state" IS 'The state.';
COMMENT ON COLUMN "qual"."mapping_coverage"."rows" IS 'Number of rows in that state.';

CREATE TABLE "qual"."mapping_rule" (
    "id" uuid NOT NULL,
    "manifest_id" text NOT NULL,
    "source_table" text NOT NULL,
    "source_field" text NOT NULL,
    "disposition" "meta"."table_disposition" NOT NULL,
    "target" text,
    "source_unit" text,
    "factor" "meta"."finite_real",
    "precision" "meta"."mapping_precision",
    "loss" text,
    "applied_rows" bigint,
    CONSTRAINT "mapping_rule__pk" PRIMARY KEY ("id"),
    CONSTRAINT "mapping_rule__identity" UNIQUE ("manifest_id", "source_table", "source_field")
);
COMMENT ON TABLE "qual"."mapping_rule" IS 'One declared rule of a mapping: a field of a source-faithful table and the canonical target it becomes, with the unit conversion applied and what the mapping loses or assumes.';
COMMENT ON COLUMN "qual"."mapping_rule"."id" IS 'Deterministic identifier of the mapping_rule instance.';
COMMENT ON COLUMN "qual"."mapping_rule"."manifest_id" IS 'The source the mapping is for.';
COMMENT ON COLUMN "qual"."mapping_rule"."source_table" IS 'The source-faithful table.';
COMMENT ON COLUMN "qual"."mapping_rule"."source_field" IS 'The field; empty for a rule about the table as a whole.';
COMMENT ON COLUMN "qual"."mapping_rule"."disposition" IS 'What the mapping does with the table.';
COMMENT ON COLUMN "qual"."mapping_rule"."target" IS 'The canonical target: a kind attribute, a relation value or a form.group.slot.';
COMMENT ON COLUMN "qual"."mapping_rule"."source_unit" IS 'The unit of the source values as the mapping declares it.';
COMMENT ON COLUMN "qual"."mapping_rule"."factor" IS 'The factor from the source unit to the target''s storage unit.';
COMMENT ON COLUMN "qual"."mapping_rule"."precision" IS 'How closely the source''s meaning matches the target.';
COMMENT ON COLUMN "qual"."mapping_rule"."loss" IS 'What the rule loses or assumes, or why the table is out of scope or deferred.';
COMMENT ON COLUMN "qual"."mapping_rule"."applied_rows" IS 'For a value rule, the number of mapped rows of its table the mapping applied it to, that is, rows for which it produced a value in a block that wrote records; absent for any other rule.';

CREATE TABLE "tk"."material" (
    "id" uuid NOT NULL,
    "registry_key" text,
    CONSTRAINT "material__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."material" IS 'A solid host or adsorbent identified by a registry or name, not by composition.';
COMMENT ON COLUMN "tk"."material"."id" IS 'Deterministic identifier of the material instance.';
COMMENT ON COLUMN "tk"."material"."registry_key" IS 'The identifier in the registry that defines it.';

CREATE TABLE "tk"."material_entity" (
    "id" uuid NOT NULL,
    "canonical_key" text NOT NULL,
    "label" text NOT NULL,
    "provisional" boolean NOT NULL DEFAULT false,
    CONSTRAINT "material_entity__pk" PRIMARY KEY ("id"),
    CONSTRAINT "material_entity__identity" UNIQUE ("canonical_key")
);
COMMENT ON TABLE "tk"."material_entity" IS 'Anything a composition coordinate can index. It requires no formula, registry number or molar mass.';
COMMENT ON COLUMN "tk"."material_entity"."id" IS 'Deterministic identifier of the material_entity instance.';
COMMENT ON COLUMN "tk"."material_entity"."canonical_key" IS 'The identity value, computed by the rule of the refinement (see each refinement).';
COMMENT ON COLUMN "tk"."material_entity"."label" IS 'A preferred display name. Never identity.';
COMMENT ON COLUMN "tk"."material_entity"."provisional" IS 'True when the entity stands for one source entity that has not been identified with a canonical entity. Records about a provisional entity are usable within their carrier and are not joined across carriers.';

CREATE TABLE "tk"."member_role" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "member_role__pk" PRIMARY KEY ("id"),
    CONSTRAINT "member_role__identity" UNIQUE ("name")
);
COMMENT ON TABLE "tk"."member_role" IS 'The part a species form plays in the phases of a chemical system: the solvent or a solute of a solution, a pure phase, a gas, a surface or exchange species. A convention set gives the standard state of each role.';
COMMENT ON COLUMN "tk"."member_role"."id" IS 'Deterministic identifier of the member_role instance.';
COMMENT ON COLUMN "tk"."member_role"."name" IS 'Name of the role.';

CREATE TABLE "tk"."model_assembly" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "title" text NOT NULL,
    "root" uuid NOT NULL,
    CONSTRAINT "model_assembly__pk" PRIMARY KEY ("id"),
    CONSTRAINT "model_assembly__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."model_assembly" IS 'A tree of form choices with every sub-form slot decided: a complete model. Named models such as PSRK, GERG-2008 and IAPWS-IF97 are assemblies.';
COMMENT ON COLUMN "tk"."model_assembly"."id" IS 'Deterministic identifier of the model_assembly instance.';
COMMENT ON COLUMN "tk"."model_assembly"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."model_assembly"."revision" IS 'Revision.';
COMMENT ON COLUMN "tk"."model_assembly"."title" IS 'Name by which the model is known.';
COMMENT ON COLUMN "tk"."model_assembly"."root" IS 'The form at the root of the tree.';

CREATE TABLE "tk"."model_component" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "model_component__pk" PRIMARY KEY ("id"),
    CONSTRAINT "model_component__identity" UNIQUE ("parameterization", "name")
);
COMMENT ON TABLE "tk"."model_component" IS 'A named component of a model that parameter sets share: a generalised departure function of a multifluid mixture model, a named function of temperature of a thermodynamic database. It is the subject of the parameter set that gives its values, and any number of other sets reference that set. Its name is scoped to a parameterisation.';
COMMENT ON COLUMN "tk"."model_component"."id" IS 'Deterministic identifier of the model_component instance.';
COMMENT ON COLUMN "tk"."model_component"."parameterization" IS 'The parameterisation the component''s name belongs to.';
COMMENT ON COLUMN "tk"."model_component"."name" IS 'The name the source gives the component.';

CREATE TABLE "param"."multifluid_departure_terms__core" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT 'd437b70d-d70f-5e20-98a9-94760f442254'::uuid,
    "c" uuid NOT NULL,
    CONSTRAINT "multifluid_departure_terms__core__pk" PRIMARY KEY ("id"),
    CONSTRAINT "multifluid_departure_terms__core__ck__slot_group" CHECK ("slot_group" = 'd437b70d-d70f-5e20-98a9-94760f442254'::uuid)
);
COMMENT ON TABLE "param"."multifluid_departure_terms__core" IS 'The term lists of one departure function.';
COMMENT ON COLUMN "param"."multifluid_departure_terms__core"."id" IS 'Deterministic identifier of the multifluid_departure_terms__core instance.';
COMMENT ON COLUMN "param"."multifluid_departure_terms__core"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."multifluid_departure_terms__core"."c" IS 'The function.';

CREATE TABLE "param"."multifluid_pair_departure_scaled__pair" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '1e45c0ef-a8af-5128-9154-875f7d089215'::uuid,
    "i" uuid NOT NULL,
    "j" uuid NOT NULL,
    "F" "meta"."scalar" NOT NULL,
    "departure" uuid NOT NULL,
    CONSTRAINT "multifluid_pair_departure_scaled__pair__pk" PRIMARY KEY ("id"),
    CONSTRAINT "multifluid_pair_departure_scaled__pair__ck__slot_group" CHECK ("slot_group" = '1e45c0ef-a8af-5128-9154-875f7d089215'::uuid),
    CONSTRAINT "multifluid_pair_departure_scaled__pair__ck__canonical" CHECK ("i" <= "j"),
    CONSTRAINT "multifluid_pair_departure_scaled__pair__ck__diagonal" CHECK ("i" <> "j")
);
COMMENT ON TABLE "param"."multifluid_pair_departure_scaled__pair" IS 'The scale factor and the departure function of one pair.';
COMMENT ON COLUMN "param"."multifluid_pair_departure_scaled__pair"."id" IS 'Deterministic identifier of the multifluid_pair_departure_scaled__pair instance.';
COMMENT ON COLUMN "param"."multifluid_pair_departure_scaled__pair"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."multifluid_pair_departure_scaled__pair"."i" IS 'The first component.';
COMMENT ON COLUMN "param"."multifluid_pair_departure_scaled__pair"."j" IS 'The second component.';
COMMENT ON COLUMN "param"."multifluid_pair_departure_scaled__pair"."F" IS 'The scale factor F_ij of the pair; zero where the pair has no departure function.';
COMMENT ON COLUMN "param"."multifluid_pair_departure_scaled__pair"."departure" IS 'The departure function of the pair, shared with the pairs that use the same one.';

CREATE TABLE "param"."multifluid_reducing__pair" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '91f581ee-ab66-513b-ab84-b9cbc8c8127b'::uuid,
    "i" uuid NOT NULL,
    "j" uuid NOT NULL,
    "arrangement" bigint NOT NULL,
    "beta_T" "meta"."scalar" NOT NULL,
    "gamma_T" "meta"."scalar" NOT NULL,
    "beta_v" "meta"."scalar" NOT NULL,
    "gamma_v" "meta"."scalar" NOT NULL,
    CONSTRAINT "multifluid_reducing__pair__pk" PRIMARY KEY ("id"),
    CONSTRAINT "multifluid_reducing__pair__ck__slot_group" CHECK ("slot_group" = '91f581ee-ab66-513b-ab84-b9cbc8c8127b'::uuid),
    CONSTRAINT "multifluid_reducing__pair__ck__arrangement_range" CHECK ("arrangement" >= 0 AND "arrangement" <= 1),
    CONSTRAINT "multifluid_reducing__pair__ck__canonical" CHECK ("i" <= "j"),
    CONSTRAINT "multifluid_reducing__pair__ck__diagonal" CHECK ("i" <> "j")
);
COMMENT ON TABLE "param"."multifluid_reducing__pair" IS 'The binary reducing parameters of one pair, held for the order the source asserted.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."id" IS 'Deterministic identifier of the multifluid_reducing__pair instance.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."i" IS 'The first component.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."j" IS 'The second component.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."arrangement" IS 'For which order of the subjects the values were asserted: 0 when the values were asserted for the canonical order of the subjects, 1 when they were asserted for the swapped order.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."beta_T" IS 'Temperature reducing ratio; its reciprocal when the pair is swapped.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."gamma_T" IS 'Temperature reducing factor; the same in both orders.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."beta_v" IS 'Volume reducing ratio; its reciprocal when the pair is swapped.';
COMMENT ON COLUMN "param"."multifluid_reducing__pair"."gamma_v" IS 'Volume reducing factor; the same in both orders.';

CREATE TABLE "param"."multifluid_reducing__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT 'b8c589f1-f5e3-549a-9589-ff38c303fc13'::uuid,
    "i" uuid NOT NULL,
    "T_c" "meta"."temperature" NOT NULL,
    "rho_c" "meta"."molar_density" NOT NULL,
    CONSTRAINT "multifluid_reducing__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "multifluid_reducing__pure__ck__slot_group" CHECK ("slot_group" = 'b8c589f1-f5e3-549a-9589-ff38c303fc13'::uuid)
);
COMMENT ON TABLE "param"."multifluid_reducing__pure" IS 'The critical parameters of one component that the reducing functions use.';
COMMENT ON COLUMN "param"."multifluid_reducing__pure"."id" IS 'Deterministic identifier of the multifluid_reducing__pure instance.';
COMMENT ON COLUMN "param"."multifluid_reducing__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."multifluid_reducing__pure"."i" IS 'The component.';
COMMENT ON COLUMN "param"."multifluid_reducing__pure"."T_c" IS 'Critical temperature.';
COMMENT ON COLUMN "param"."multifluid_reducing__pure"."rho_c" IS 'Critical density.';

CREATE TABLE "tk"."naming_scheme" (
    "id" uuid NOT NULL,
    "name" text NOT NULL,
    "structural" boolean NOT NULL,
    "registry" boolean NOT NULL,
    CONSTRAINT "naming_scheme__pk" PRIMARY KEY ("id"),
    CONSTRAINT "naming_scheme__identity" UNIQUE ("name")
);
COMMENT ON TABLE "tk"."naming_scheme" IS 'A system of names or registry identifiers that sources use to refer to material: a registry, a structure notation, or a source''s own labels.';
COMMENT ON COLUMN "tk"."naming_scheme"."id" IS 'Deterministic identifier of the naming_scheme instance.';
COMMENT ON COLUMN "tk"."naming_scheme"."name" IS 'Name of the scheme.';
COMMENT ON COLUMN "tk"."naming_scheme"."structural" IS 'True when the value encodes chemical structure, so equal canonical values imply equal structure.';
COMMENT ON COLUMN "tk"."naming_scheme"."registry" IS 'True when the value is an entry in an external registry of substances, so that the corpus can cross-reference it to a structure.';

CREATE TABLE "param"."nasa7__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '3ee2acab-9ebb-5ee6-9279-9e7968621ba1'::uuid,
    "i" uuid NOT NULL,
    CONSTRAINT "nasa7__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "nasa7__pure__ck__slot_group" CHECK ("slot_group" = '3ee2acab-9ebb-5ee6-9279-9e7968621ba1'::uuid)
);
COMMENT ON TABLE "param"."nasa7__pure" IS 'The coefficient blocks of one species form.';
COMMENT ON COLUMN "param"."nasa7__pure"."id" IS 'Deterministic identifier of the nasa7__pure instance.';
COMMENT ON COLUMN "param"."nasa7__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."nasa7__pure"."i" IS 'The species form.';

CREATE TABLE "param"."nasa9__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '07eb75cf-d58c-5939-a34a-c85cc14c0972'::uuid,
    "i" uuid NOT NULL,
    CONSTRAINT "nasa9__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "nasa9__pure__ck__slot_group" CHECK ("slot_group" = '07eb75cf-d58c-5939-a34a-c85cc14c0972'::uuid)
);
COMMENT ON TABLE "param"."nasa9__pure" IS 'The coefficient blocks of one species form.';
COMMENT ON COLUMN "param"."nasa9__pure"."id" IS 'Deterministic identifier of the nasa9__pure instance.';
COMMENT ON COLUMN "param"."nasa9__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."nasa9__pure"."i" IS 'The species form.';

CREATE TABLE "tk"."observable" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "quantity" uuid NOT NULL,
    "subject" "meta"."subject_shape" NOT NULL,
    "basis" "meta"."amount_basis" NOT NULL,
    "relation" "meta"."reference_relation" NOT NULL,
    "path" "meta"."path" NOT NULL,
    "adsorption" "meta"."adsorption_kind" NOT NULL DEFAULT 'not_applicable',
    "diffusion" "meta"."diffusion_frame" NOT NULL DEFAULT 'not_applicable',
    CONSTRAINT "observable__pk" PRIMARY KEY ("id"),
    CONSTRAINT "observable__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."observable" IS 'A physical quantity with the facets needed to interpret a number for it.';
COMMENT ON COLUMN "tk"."observable"."id" IS 'Deterministic identifier of the observable instance.';
COMMENT ON COLUMN "tk"."observable"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."observable"."quantity" IS 'The quantity type values are stored in.';
COMMENT ON COLUMN "tk"."observable"."subject" IS 'What it is a property of.';
COMMENT ON COLUMN "tk"."observable"."basis" IS 'What it is divided by.';
COMMENT ON COLUMN "tk"."observable"."relation" IS 'What it is relative to.';
COMMENT ON COLUMN "tk"."observable"."path" IS 'The path along which it is defined.';
COMMENT ON COLUMN "tk"."observable"."adsorption" IS 'Which adsorbed amount, for an adsorption observable.';
COMMENT ON COLUMN "tk"."observable"."diffusion" IS 'The frame of reference, for a diffusion observable.';

CREATE TABLE "tk"."observable_alias" (
    "id" uuid NOT NULL,
    "carrier_scope" text NOT NULL,
    "name" text NOT NULL,
    "observable" uuid NOT NULL,
    "precision" "meta"."mapping_precision" NOT NULL,
    "loss" text,
    CONSTRAINT "observable_alias__pk" PRIMARY KEY ("id"),
    CONSTRAINT "observable_alias__identity" UNIQUE ("carrier_scope", "name")
);
COMMENT ON TABLE "tk"."observable_alias" IS 'A source''s name for an observable. The mapping states its precision and what it loses.';
COMMENT ON COLUMN "tk"."observable_alias"."id" IS 'Deterministic identifier of the observable_alias instance.';
COMMENT ON COLUMN "tk"."observable_alias"."carrier_scope" IS 'The vocabulary the name belongs to, such as `thermoml` or `cape_open_1_1`.';
COMMENT ON COLUMN "tk"."observable_alias"."name" IS 'The name, verbatim.';
COMMENT ON COLUMN "tk"."observable_alias"."observable" IS 'The observable it denotes.';
COMMENT ON COLUMN "tk"."observable_alias"."precision" IS 'How closely the source''s meaning matches.';
COMMENT ON COLUMN "tk"."observable_alias"."loss" IS 'What the mapping loses or assumes, when it is not exact.';

CREATE TABLE "tk"."parameter_set" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "slot_group" uuid NOT NULL,
    "subject_key" text NOT NULL,
    "occurrence" bigint NOT NULL DEFAULT 1,
    "parent" uuid,
    "parent_slot" uuid,
    CONSTRAINT "parameter_set__pk" PRIMARY KEY ("id"),
    CONSTRAINT "parameter_set__identity" UNIQUE ("parameterization", "slot_group", "subject_key", "occurrence"),
    CONSTRAINT "parameter_set__uq__id_slot_group" UNIQUE ("id", "slot_group"),
    CONSTRAINT "parameter_set__ck__occurrence_from_one" CHECK ("occurrence" > 0)
);
COMMENT ON TABLE "tk"."parameter_set" IS 'One source''s coherent values for one slot group and one subject tuple, with its indexed children. Each slot group is a refinement of this kind.';
COMMENT ON COLUMN "tk"."parameter_set"."id" IS 'Deterministic identifier of the parameter_set instance.';
COMMENT ON COLUMN "tk"."parameter_set"."parameterization" IS 'The collection the set belongs to.';
COMMENT ON COLUMN "tk"."parameter_set"."slot_group" IS 'The slot group the set instantiates.';
COMMENT ON COLUMN "tk"."parameter_set"."subject_key" IS 'Canonical encoding of the subject identifiers in role order; for a nested set, the parent set, slot and index.';
COMMENT ON COLUMN "tk"."parameter_set"."occurrence" IS 'Distinguishes repeated assertions for one subject within one parameterisation, from one in source order. A source that lists a pair twice with different values has two sets; which one the source''s own code uses is a selection fact, not a reason to drop the other.';
COMMENT ON COLUMN "tk"."parameter_set"."parent" IS 'The set this one is a nested value of.';
COMMENT ON COLUMN "tk"."parameter_set"."parent_slot" IS 'The slot of the parent this set is the value of.';

CREATE TABLE "tk"."parameterization" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "title" text NOT NULL,
    "coherence" "meta"."coherence" NOT NULL,
    "convention_set" uuid,
    "site_scheme" uuid,
    "group_scheme" uuid,
    "chemical_system" uuid,
    "composition_basis" uuid,
    "reference_volume" "meta"."molar_volume",
    CONSTRAINT "parameterization__pk" PRIMARY KEY ("id"),
    CONSTRAINT "parameterization__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."parameterization" IS 'A published collection of parameter sets meant to be used together, under one convention set.';
COMMENT ON COLUMN "tk"."parameterization"."id" IS 'Deterministic identifier of the parameterization instance.';
COMMENT ON COLUMN "tk"."parameterization"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."parameterization"."revision" IS 'Revision, publication year or carrier pin.';
COMMENT ON COLUMN "tk"."parameterization"."title" IS 'Name by which the collection is known.';
COMMENT ON COLUMN "tk"."parameterization"."coherence" IS 'How its sets relate to each other.';
COMMENT ON COLUMN "tk"."parameterization"."convention_set" IS 'The conventions its values assume.';
COMMENT ON COLUMN "tk"."parameterization"."site_scheme" IS 'The association site scheme its sets assume, where one applies.';
COMMENT ON COLUMN "tk"."parameterization"."group_scheme" IS 'The group scheme its sets are scoped to, where one applies.';
COMMENT ON COLUMN "tk"."parameterization"."chemical_system" IS 'The chemical system its sets belong to, where one applies.';
COMMENT ON COLUMN "tk"."parameterization"."composition_basis" IS 'The composition basis its interaction values assume, where the form leaves it open.';
COMMENT ON COLUMN "tk"."parameterization"."reference_volume" IS 'The reference volume its size ratios and interaction values are relative to, where the form leaves it open.';

CREATE TABLE "tk"."phase_definition" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "key" text NOT NULL,
    "aggregation" uuid NOT NULL,
    "structure" "meta"."phase_structure" NOT NULL,
    "prototype" text,
    "source_directives" text,
    CONSTRAINT "phase_definition__pk" PRIMARY KEY ("id"),
    CONSTRAINT "phase_definition__identity" UNIQUE ("system", "key")
);
COMMENT ON TABLE "tk"."phase_definition" IS 'A named solution or pure phase within a chemical system: its aggregation, constituents and internal structure.';
COMMENT ON COLUMN "tk"."phase_definition"."id" IS 'Deterministic identifier of the phase_definition instance.';
COMMENT ON COLUMN "tk"."phase_definition"."system" IS 'The system the phase belongs to.';
COMMENT ON COLUMN "tk"."phase_definition"."key" IS 'The phase''s name in that system.';
COMMENT ON COLUMN "tk"."phase_definition"."aggregation" IS 'Its state of aggregation.';
COMMENT ON COLUMN "tk"."phase_definition"."structure" IS 'The internal structure it assumes.';
COMMENT ON COLUMN "tk"."phase_definition"."prototype" IS 'A structure prototype or Strukturbericht designation, where the source gives one.';
COMMENT ON COLUMN "tk"."phase_definition"."source_directives" IS 'Uninterpreted source directives attached to the phase, retained verbatim.';

CREATE TABLE "tk"."polymer_type" (
    "id" uuid NOT NULL,
    "architecture" text,
    CONSTRAINT "polymer_type__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."polymer_type" IS 'A polymer identified by its repeat units and architecture. A molar-mass distribution is a property of a sample or mixture, not of the type.';
COMMENT ON COLUMN "tk"."polymer_type"."id" IS 'Deterministic identifier of the polymer_type instance.';
COMMENT ON COLUMN "tk"."polymer_type"."architecture" IS 'Linear, branched, block and similar, as the source states it.';

CREATE TABLE "tk"."pseudo_component" (
    "id" uuid NOT NULL,
    "kind" "meta"."pseudo_component_kind" NOT NULL,
    "produced_by" uuid,
    CONSTRAINT "pseudo_component__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."pseudo_component" IS 'An entity defined by characterisation or by fiat, without a formula. Its molar mass is asserted or estimated with provenance, never derived. Canonical key: the derivation that produced it and its index, or its own declared key.';
COMMENT ON COLUMN "tk"."pseudo_component"."id" IS 'Deterministic identifier of the pseudo_component instance.';
COMMENT ON COLUMN "tk"."pseudo_component"."kind" IS 'Why it has no formula.';
COMMENT ON COLUMN "tk"."pseudo_component"."produced_by" IS 'The characterisation that produced it.';

CREATE TABLE "prov"."publication" (
    "id" uuid NOT NULL,
    "doi" "meta"."id_doi",
    "isbn" "meta"."id_isbn",
    CONSTRAINT "publication__pk" PRIMARY KEY ("id"),
    CONSTRAINT "publication__uq__doi" UNIQUE ("doi")
);
COMMENT ON TABLE "prov"."publication" IS 'A published work that content is attributed to. Its identity is bound to the work: the key is `doi:` and the lower-case DOI when the work has one, so two carriers citing one paper under different citation keys name one publication, and otherwise `carrier:`, the citing carrier''s manifest id, `:` and its citation key. What a carrier says about the work (its citation key, year and citation text) is per carrier and lives on the `citation` relation, so carriers that differ in it still agree on the publication.';
COMMENT ON COLUMN "prov"."publication"."id" IS 'Deterministic identifier of the publication instance.';
COMMENT ON COLUMN "prov"."publication"."doi" IS 'The DOI in lower case, where one exists.';
COMMENT ON COLUMN "prov"."publication"."isbn" IS 'ISBN for a book.';

CREATE TABLE "tk"."purification_method" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "name" text NOT NULL,
    CONSTRAINT "purification_method__pk" PRIMARY KEY ("id"),
    CONSTRAINT "purification_method__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."purification_method" IS 'A purification method, from a vocabulary a mapping declares.';
COMMENT ON COLUMN "tk"."purification_method"."id" IS 'Deterministic identifier of the purification_method instance.';
COMMENT ON COLUMN "tk"."purification_method"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."purification_method"."name" IS 'The method''s name as its source writes it.';

CREATE TABLE "qual"."qualification_run" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "form" uuid NOT NULL,
    "expression_hash" "meta"."hash" NOT NULL,
    "basis" "meta"."comparison_basis" NOT NULL,
    "reference" uuid,
    "outcome" "meta"."run_outcome" NOT NULL,
    "points" bigint NOT NULL,
    "relative_tolerance" "meta"."scalar" NOT NULL,
    "observable" uuid,
    "absolute_tolerance" "meta"."finite_real",
    "worst_relative_deviation" "meta"."scalar",
    "blocked_reason" "meta"."blocked_reason",
    "note" text,
    "validity_kind" "meta"."envelope_kind",
    "inside_points" bigint,
    "outside_points" bigint,
    "undetermined_points" bigint,
    CONSTRAINT "qualification_run__pk" PRIMARY KEY ("id"),
    CONSTRAINT "qualification_run__identity" UNIQUE ("key"),
    CONSTRAINT "qualification_run__ck__blocked_reason_iff_blocked" CHECK (("blocked_reason" IS NOT NULL) = ("outcome"::text IN ('blocked')))
);
COMMENT ON TABLE "qual"."qualification_run" IS 'One comparison of a form, evaluated from canonical records, against an independent answer over a declared domain.';
COMMENT ON COLUMN "qual"."qualification_run"."id" IS 'Deterministic identifier of the qualification_run instance.';
COMMENT ON COLUMN "qual"."qualification_run"."key" IS 'Stable key: form, parameter set or sets, comparison basis and declaration fingerprint.';
COMMENT ON COLUMN "qual"."qualification_run"."form" IS 'The form evaluated.';
COMMENT ON COLUMN "qual"."qualification_run"."expression_hash" IS 'Hash of what evaluating the compared output reads from the form''s text (its locals, the output''s expression and its implicit blocks, canonically serialised): the run speaks for the form only while the form''s current hash in `meta.form_output.evaluation_hash` equals it.';
COMMENT ON COLUMN "qual"."qualification_run"."basis" IS 'What it was compared against.';
COMMENT ON COLUMN "qual"."qualification_run"."reference" IS 'The library release or publication that supplied the reference answers; absent for a run blocked before the reference was known.';
COMMENT ON COLUMN "qual"."qualification_run"."outcome" IS 'How the run ended.';
COMMENT ON COLUMN "qual"."qualification_run"."points" IS 'Number of points compared.';
COMMENT ON COLUMN "qual"."qualification_run"."relative_tolerance" IS 'Declared relative tolerance.';
COMMENT ON COLUMN "qual"."qualification_run"."observable" IS 'The observable of the contract output compared, where the output denotes one.';
COMMENT ON COLUMN "qual"."qualification_run"."absolute_tolerance" IS 'Declared absolute tolerance in the observable''s storage unit.';
COMMENT ON COLUMN "qual"."qualification_run"."worst_relative_deviation" IS 'Largest relative deviation observed.';
COMMENT ON COLUMN "qual"."qualification_run"."blocked_reason" IS 'Why a blocked run could not be carried out; present exactly when the outcome is `blocked`.';
COMMENT ON COLUMN "qual"."qualification_run"."note" IS 'The detail of a blocked run''s reason, or what the domain excluded.';
COMMENT ON COLUMN "qual"."qualification_run"."validity_kind" IS 'The kind of validity region the counts of points below are taken against; stated by a case that names one.';
COMMENT ON COLUMN "qual"."qualification_run"."inside_points" IS 'Grid points that lay inside a region of that kind on every record the evaluation read that states one.';
COMMENT ON COLUMN "qual"."qualification_run"."outside_points" IS 'Grid points that lay outside one, including those a case excluded for it.';
COMMENT ON COLUMN "qual"."qualification_run"."undetermined_points" IS 'Grid points that are outside no region of that kind and inside none, because a clause cannot be decided from the arguments: it is about a component or a phase or limits an observable no argument of the contract names.';

CREATE TABLE "tk"."reaction" (
    "id" uuid NOT NULL,
    "canonical_key" text NOT NULL,
    "extent" "meta"."extent_convention" NOT NULL,
    "equation" text,
    CONSTRAINT "reaction__pk" PRIMARY KEY ("id"),
    CONSTRAINT "reaction__identity" UNIQUE ("canonical_key")
);
COMMENT ON TABLE "tk"."reaction" IS 'A stoichiometry over species forms. Canonical key: the participants'' identifiers and coefficients in a normalised order, with the extent convention.';
COMMENT ON COLUMN "tk"."reaction"."id" IS 'Deterministic identifier of the reaction instance.';
COMMENT ON COLUMN "tk"."reaction"."canonical_key" IS 'Canonical encoding of the normalised stoichiometry.';
COMMENT ON COLUMN "tk"."reaction"."extent" IS 'How the stoichiometry is normalised.';
COMMENT ON COLUMN "tk"."reaction"."equation" IS 'The reaction as the source writes it. Retained; nothing branches on it.';

CREATE TABLE "tk"."region_clause" (
    "id" uuid NOT NULL,
    "region" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "observable" uuid NOT NULL,
    "component" uuid,
    "aggregation" uuid,
    "lower" "meta"."finite_real",
    "upper" "meta"."finite_real",
    "lower_relative_to" uuid,
    "upper_relative_to" uuid,
    CONSTRAINT "region_clause__pk" PRIMARY KEY ("id"),
    CONSTRAINT "region_clause__identity" UNIQUE ("region", "ordinal"),
    CONSTRAINT "region_clause__ck__ordinal_from_one" CHECK ("ordinal" > 0),
    CONSTRAINT "region_clause__ck__bounds_ordered" CHECK ("lower" IS NULL OR "upper" IS NULL OR "lower_relative_to" IS DISTINCT FROM "upper_relative_to" OR "lower" <= "upper")
);
COMMENT ON TABLE "tk"."region_clause" IS 'One condition of a validity region: an interval of one observable, about the whole record or, through a component or an aggregation, about one component or one phase of it.';
COMMENT ON COLUMN "tk"."region_clause"."id" IS 'Deterministic identifier of the region_clause instance.';
COMMENT ON COLUMN "tk"."region_clause"."region" IS 'The region the clause belongs to.';
COMMENT ON COLUMN "tk"."region_clause"."ordinal" IS 'Position among the clauses of the region, from one.';
COMMENT ON COLUMN "tk"."region_clause"."observable" IS 'The axis the clause limits: the observable of a condition such as temperature or pressure, or of a composition or a partial quantity.';
COMMENT ON COLUMN "tk"."region_clause"."component" IS 'The component the clause is about, for a composition or a partial quantity.';
COMMENT ON COLUMN "tk"."region_clause"."aggregation" IS 'The aggregation whose phase the clause is about.';
COMMENT ON COLUMN "tk"."region_clause"."lower" IS 'Lower bound in the observable''s storage unit; absent when the clause has no lower limit. With `lower_relative_to`, the offset from the subject''s value of that observable, in the same unit.';
COMMENT ON COLUMN "tk"."region_clause"."upper" IS 'Upper bound in the observable''s storage unit; absent when the clause has no upper limit. With `upper_relative_to`, the offset from the subject''s value of that observable, in the same unit.';
COMMENT ON COLUMN "tk"."region_clause"."lower_relative_to" IS 'The observable of the subject whose value the lower bound is an offset from (the normal boiling temperature minus 50 K: the boiling temperature and an offset of -50 K). Absent for a bound stated as a value. It has the quantity type of the clause''s observable.';
COMMENT ON COLUMN "tk"."region_clause"."upper_relative_to" IS 'The observable of the subject whose value the upper bound is an offset from (the critical temperature minus 100 K). Absent for a bound stated as a value. It has the quantity type of the clause''s observable.';

CREATE TABLE "tk"."resolved_snapshot" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "assembly" uuid NOT NULL,
    "policy" uuid NOT NULL,
    CONSTRAINT "resolved_snapshot__pk" PRIMARY KEY ("id"),
    CONSTRAINT "resolved_snapshot__identity" UNIQUE ("key", "revision")
);
COMMENT ON TABLE "tk"."resolved_snapshot" IS 'The frozen result of applying a selection policy to a model assembly and a set of entities. The snapshot export, a later packet, establishes for it exactly one value per required slot and subject, every dependency of the selected sets satisfied or waived, compatible conventions and no record whose rights forbid the use. It is the boundary between this open-world store and a closed-world package.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."id" IS 'Deterministic identifier of the resolved_snapshot instance.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."revision" IS 'Revision.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."assembly" IS 'The model the snapshot resolves.';
COMMENT ON COLUMN "tk"."resolved_snapshot"."policy" IS 'The policy applied.';

CREATE TABLE "prov"."rights_determination" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "scope" text NOT NULL,
    "ordinal" bigint NOT NULL,
    "basis" "meta"."rights_basis" NOT NULL,
    "licence" uuid,
    "statement" text NOT NULL,
    "url" text,
    "store" "meta"."permission" NOT NULL,
    "redistribute" "meta"."permission" NOT NULL,
    "commercial" "meta"."permission" NOT NULL,
    "attribution_required" boolean NOT NULL,
    "share_alike" boolean NOT NULL,
    "observed" text NOT NULL,
    CONSTRAINT "rights_determination__pk" PRIMARY KEY ("id"),
    CONSTRAINT "rights_determination__identity" UNIQUE ("carrier", "scope", "ordinal")
);
COMMENT ON TABLE "prov"."rights_determination" IS 'A recorded claim about what may be done with part of a carrier. Competing claims about one scope are all kept; the model records claims and does not decide law.';
COMMENT ON COLUMN "prov"."rights_determination"."id" IS 'Deterministic identifier of the rights_determination instance.';
COMMENT ON COLUMN "prov"."rights_determination"."carrier" IS 'The carrier the claim concerns.';
COMMENT ON COLUMN "prov"."rights_determination"."scope" IS '`code`, `data`, or a path glob within the carrier.';
COMMENT ON COLUMN "prov"."rights_determination"."ordinal" IS 'Order among claims with the same carrier and scope.';
COMMENT ON COLUMN "prov"."rights_determination"."basis" IS 'What the claim rests on.';
COMMENT ON COLUMN "prov"."rights_determination"."licence" IS 'The licence the determination names.';
COMMENT ON COLUMN "prov"."rights_determination"."statement" IS 'The governing statement, quoted or closely paraphrased.';
COMMENT ON COLUMN "prov"."rights_determination"."url" IS 'Where the statement was read.';
COMMENT ON COLUMN "prov"."rights_determination"."store" IS 'Keeping a local copy.';
COMMENT ON COLUMN "prov"."rights_determination"."redistribute" IS 'Passing the content on.';
COMMENT ON COLUMN "prov"."rights_determination"."commercial" IS 'Commercial use.';
COMMENT ON COLUMN "prov"."rights_determination"."attribution_required" IS 'Whether attribution is required.';
COMMENT ON COLUMN "prov"."rights_determination"."share_alike" IS 'Whether derived works must carry the same terms.';
COMMENT ON COLUMN "prov"."rights_determination"."observed" IS 'When and how the claim was established.';

CREATE TABLE "tk"."sample" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "local_key" text NOT NULL,
    "entity" uuid NOT NULL,
    "source" "meta"."sample_source" NOT NULL,
    "status" "meta"."sample_status" NOT NULL,
    "supplier" text,
    CONSTRAINT "sample__pk" PRIMARY KEY ("id"),
    CONSTRAINT "sample__identity" UNIQUE ("carrier", "local_key")
);
COMMENT ON TABLE "tk"."sample" IS 'A physical batch of an entity as used in a measurement.';
COMMENT ON COLUMN "tk"."sample"."id" IS 'Deterministic identifier of the sample instance.';
COMMENT ON COLUMN "tk"."sample"."carrier" IS 'The carrier that describes the sample.';
COMMENT ON COLUMN "tk"."sample"."local_key" IS 'The sample''s key within that carrier.';
COMMENT ON COLUMN "tk"."sample"."entity" IS 'What the sample is a batch of.';
COMMENT ON COLUMN "tk"."sample"."source" IS 'Where the sample came from: a commercial source, a synthesis, a reference material, a natural product, or not stated.';
COMMENT ON COLUMN "tk"."sample"."status" IS 'Whether and where the sample is described.';
COMMENT ON COLUMN "tk"."sample"."supplier" IS 'The name of the supplier, as the source gives it.';

CREATE TABLE "tk"."selection_policy" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "revision" text NOT NULL,
    "unasserted" "meta"."unasserted_policy" NOT NULL,
    "rule_form" uuid,
    "asserted_by" uuid,
    "scope_slot_group" uuid,
    "scope_observable" uuid,
    "repeated_rows" "meta"."repeated_row_rule",
    "table_choice" "meta"."table_choice_rule",
    "as_documented" boolean,
    CONSTRAINT "selection_policy__pk" PRIMARY KEY ("id"),
    CONSTRAINT "selection_policy__identity" UNIQUE ("key", "revision"),
    CONSTRAINT "selection_policy__ck__rule_form_for_named_rule" CHECK (("rule_form" IS NOT NULL) = ("unasserted"::text IN ('named_rule')))
);
COMMENT ON TABLE "tk"."selection_policy" IS 'An ordered preference among parameterisations, with per-subject overrides, the defaults it states for slots (`policy_default`) and a stated behaviour when nothing is asserted. Applying it is deterministic. A carrier''s own behaviour is a policy whose `asserted_by` is that carrier, scoped to one slot group or one observable, and saying whether it is what the carrier documents: a repeated row that wins by coming last, a default table chosen by dictionary order, an in-band `DEFAULT` tag or a library rank.';
COMMENT ON COLUMN "tk"."selection_policy"."id" IS 'Deterministic identifier of the selection_policy instance.';
COMMENT ON COLUMN "tk"."selection_policy"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."selection_policy"."revision" IS 'Revision.';
COMMENT ON COLUMN "tk"."selection_policy"."unasserted" IS 'What to do when no set is asserted for a required subject.';
COMMENT ON COLUMN "tk"."selection_policy"."rule_form" IS 'The form that computes the value of an unasserted subject, when `unasserted` is `named_rule`: a combining rule such as Lorentz-Berthelot declared as a form whose output is the pair value.';
COMMENT ON COLUMN "tk"."selection_policy"."asserted_by" IS 'The carrier whose own default behaviour this policy records; absent for a policy authored for a snapshot.';
COMMENT ON COLUMN "tk"."selection_policy"."scope_slot_group" IS 'The slot group the policy governs, when it is narrower than everything.';
COMMENT ON COLUMN "tk"."selection_policy"."scope_observable" IS 'The observable the policy governs, when it is narrower than everything.';
COMMENT ON COLUMN "tk"."selection_policy"."repeated_rows" IS 'For a carrier''s policy: which of several rows for one subject under one selector the carrier''s own code uses, within the scope. The rows themselves are all held, distinguished by their occurrence.';
COMMENT ON COLUMN "tk"."selection_policy"."table_choice" IS 'For a carrier''s policy: how the carrier chooses among competing tables within the scope when the caller names none. The order it yields is the policy''s precedence.';
COMMENT ON COLUMN "tk"."selection_policy"."as_documented" IS 'For a carrier''s policy: whether the behaviour recorded, which is what the code does, matches what the carrier documents. False where the documented order and the code differ.';

CREATE TABLE "param"."shomate__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '57160327-fa37-51f8-9549-02af8691b569'::uuid,
    "i" uuid NOT NULL,
    CONSTRAINT "shomate__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "shomate__pure__ck__slot_group" CHECK ("slot_group" = '57160327-fa37-51f8-9549-02af8691b569'::uuid)
);
COMMENT ON TABLE "param"."shomate__pure" IS 'The coefficient blocks of one species form.';
COMMENT ON COLUMN "param"."shomate__pure"."id" IS 'Deterministic identifier of the shomate__pure instance.';
COMMENT ON COLUMN "param"."shomate__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."shomate__pure"."i" IS 'The species form.';

CREATE TABLE "tk"."site_class" (
    "id" uuid NOT NULL,
    "host_key" text NOT NULL,
    "index" bigint NOT NULL,
    "phase" uuid,
    "material" uuid,
    "label" text,
    "ratio_kind" "meta"."site_ratio_kind" NOT NULL,
    "ratio" "meta"."count",
    CONSTRAINT "site_class__pk" PRIMARY KEY ("id"),
    CONSTRAINT "site_class__identity" UNIQUE ("host_key", "index"),
    CONSTRAINT "site_class__ck__one_host" CHECK (num_nonnulls("phase", "material") = 1),
    CONSTRAINT "site_class__ck__index_positive" CHECK ("index" > 0)
);
COMMENT ON TABLE "tk"."site_class" IS 'A sublattice, hydrate cage, surface site type or exchanger: a class of positions that constituents occupy, within a phase definition or on a material.';
COMMENT ON COLUMN "tk"."site_class"."id" IS 'Deterministic identifier of the site_class instance.';
COMMENT ON COLUMN "tk"."site_class"."host_key" IS 'Identifier of the hosting phase definition or material, as text, so the identity is one tuple for both cases.';
COMMENT ON COLUMN "tk"."site_class"."index" IS 'Position of the class within its host, from one.';
COMMENT ON COLUMN "tk"."site_class"."phase" IS 'The hosting phase definition.';
COMMENT ON COLUMN "tk"."site_class"."material" IS 'The hosting material.';
COMMENT ON COLUMN "tk"."site_class"."label" IS 'The class''s name in the source.';
COMMENT ON COLUMN "tk"."site_class"."ratio_kind" IS 'Whether the site ratio is a constant.';
COMMENT ON COLUMN "tk"."site_class"."ratio" IS 'Sites per formula unit, when constant.';

CREATE TABLE "tk"."site_scheme" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    CONSTRAINT "site_scheme__pk" PRIMARY KEY ("id"),
    CONSTRAINT "site_scheme__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."site_scheme" IS 'A named way of assigning association sites, such as 2B or 4C. It is part of a parameterisation: the same species under two site schemes is two different sets of parameters.';
COMMENT ON COLUMN "tk"."site_scheme"."id" IS 'Deterministic identifier of the site_scheme instance.';
COMMENT ON COLUMN "tk"."site_scheme"."key" IS 'Stable key of the scheme.';

CREATE TABLE "tk"."slot_uncertainty" (
    "id" uuid NOT NULL,
    "parameter_set" uuid NOT NULL,
    "slot" uuid NOT NULL,
    "index_key" text NOT NULL,
    "kind" "meta"."uncertainty_kind" NOT NULL,
    "magnitude" "meta"."finite_real",
    "relative_magnitude" "meta"."scalar",
    "coverage_factor" "meta"."scalar",
    "confidence_level" "meta"."fraction",
    CONSTRAINT "slot_uncertainty__pk" PRIMARY KEY ("id"),
    CONSTRAINT "slot_uncertainty__identity" UNIQUE ("parameter_set", "slot", "index_key")
);
COMMENT ON TABLE "tk"."slot_uncertainty" IS 'The uncertainty a source states for one slot value. Joint covariance belongs to the fit that produced the values.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."id" IS 'Deterministic identifier of the slot_uncertainty instance.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."parameter_set" IS 'The set.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."slot" IS 'The slot.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."index_key" IS 'Canonical encoding of the family index, empty for a slot outside any family.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."kind" IS 'What the magnitude means.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."magnitude" IS 'The magnitude of a standard, expanded or interval uncertainty, in the slot''s storage unit.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."relative_magnitude" IS 'The magnitude of an uncertainty whose kind is dimensionless: a fraction of the value for a relative kind, the factor f for a multiplicative one.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."coverage_factor" IS 'Coverage factor of an expanded uncertainty.';
COMMENT ON COLUMN "tk"."slot_uncertainty"."confidence_level" IS 'Level of confidence of an expanded uncertainty.';

CREATE TABLE "prov"."software_release" (
    "id" uuid NOT NULL,
    "version" text NOT NULL,
    "homepage" text,
    CONSTRAINT "software_release__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "prov"."software_release" IS 'A released version of a program or library, as the origin of a computation or the reference of a comparison.';
COMMENT ON COLUMN "prov"."software_release"."id" IS 'Deterministic identifier of the software_release instance.';
COMMENT ON COLUMN "prov"."software_release"."version" IS 'The release version.';
COMMENT ON COLUMN "prov"."software_release"."homepage" IS 'Where the release is published.';

CREATE TABLE "prov"."source" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "title" text NOT NULL,
    CONSTRAINT "source__pk" PRIMARY KEY ("id"),
    CONSTRAINT "source__identity" UNIQUE ("key")
);
COMMENT ON TABLE "prov"."source" IS 'An attributable origin of content: a publication, a software release, a database release or an acquired carrier.';
COMMENT ON COLUMN "prov"."source"."id" IS 'Deterministic identifier of the source instance.';
COMMENT ON COLUMN "prov"."source"."key" IS 'Stable key: the manifest id and resolved pin for a carrier; `doi:` and the lower-case DOI for a publication that has one, otherwise `carrier:`, the manifest id of the carrier that cites it, `:` and that carrier''s citation key.';
COMMENT ON COLUMN "prov"."source"."title" IS 'Human-readable title.';

CREATE TABLE "tk"."source_entity" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "scope" text NOT NULL,
    "local_key" text NOT NULL,
    "entity_class" "meta"."entity_class" NOT NULL,
    "aggregation" uuid,
    "polymorph" text,
    "stated_charge" "meta"."charge_number",
    "status" "meta"."resolution_status" NOT NULL,
    "rule" "meta"."resolution_rule" NOT NULL,
    "target" uuid NOT NULL,
    CONSTRAINT "source_entity__pk" PRIMARY KEY ("id"),
    CONSTRAINT "source_entity__identity" UNIQUE ("carrier", "scope", "local_key"),
    CONSTRAINT "source_entity__ck__local_key_nonempty" CHECK ("local_key" <> '')
);
COMMENT ON TABLE "tk"."source_entity" IS 'The thing a carrier means by one of its keys: a file name, a row name, a registry number used as a key. A source''s records are about source entities until resolution identifies each with a material entity. A provider name is never silently promoted to a canonical identity.';
COMMENT ON COLUMN "tk"."source_entity"."id" IS 'Deterministic identifier of the source_entity instance.';
COMMENT ON COLUMN "tk"."source_entity"."carrier" IS 'The carrier whose key this is.';
COMMENT ON COLUMN "tk"."source_entity"."scope" IS 'The context within the carrier in which the key is unique, such as a table or database file; empty when carrier-wide.';
COMMENT ON COLUMN "tk"."source_entity"."local_key" IS 'The key, verbatim.';
COMMENT ON COLUMN "tk"."source_entity"."entity_class" IS 'The class of thing the source says the key names, as its mapping declares it; it selects the resolution rules.';
COMMENT ON COLUMN "tk"."source_entity"."aggregation" IS 'The state of aggregation the source states for the entity, when its records are about a form rather than a chemical identity.';
COMMENT ON COLUMN "tk"."source_entity"."polymorph" IS 'The polymorph or structure designation the source states.';
COMMENT ON COLUMN "tk"."source_entity"."stated_charge" IS 'The net charge the source states for the entity, where it states one.';
COMMENT ON COLUMN "tk"."source_entity"."status" IS 'Where its resolution stands.';
COMMENT ON COLUMN "tk"."source_entity"."rule" IS 'Which rule decided it.';
COMMENT ON COLUMN "tk"."source_entity"."target" IS 'The entity its records are attached to: the canonical entity when resolved, otherwise a provisional one.';

CREATE TABLE "tk"."speciation_map" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "key" text NOT NULL,
    "exactness" "meta"."map_exactness" NOT NULL,
    "invertible" boolean NOT NULL,
    CONSTRAINT "speciation_map__pk" PRIMARY KEY ("id"),
    CONSTRAINT "speciation_map__identity" UNIQUE ("system", "key")
);
COMMENT ON TABLE "tk"."speciation_map" IS 'The relation between an apparent description of a material and its true species within a chemical system. Apparent and true are two descriptions of one material account, never two inventories.';
COMMENT ON COLUMN "tk"."speciation_map"."id" IS 'Deterministic identifier of the speciation_map instance.';
COMMENT ON COLUMN "tk"."speciation_map"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."speciation_map"."key" IS 'Name of the map.';
COMMENT ON COLUMN "tk"."speciation_map"."exactness" IS 'Whether the map is a constant linear map.';
COMMENT ON COLUMN "tk"."speciation_map"."invertible" IS 'Whether the apparent description can be recovered from the true one.';

CREATE TABLE "tk"."species" (
    "id" uuid NOT NULL,
    "charge" "meta"."charge_number" NOT NULL DEFAULT 0.0,
    "inchikey" "meta"."id_inchikey",
    CONSTRAINT "species__pk" PRIMARY KEY ("id"),
    CONSTRAINT "species__uq__inchikey" UNIQUE ("inchikey")
);
COMMENT ON TABLE "tk"."species" IS 'A chemical identity: formula, charge and, where known, structure. A vacancy and the electron are species with an empty formula. Canonical key: the standard InChIKey where one is resolved, otherwise formula, charge and a declared discriminator.';
COMMENT ON COLUMN "tk"."species"."id" IS 'Deterministic identifier of the species instance.';
COMMENT ON COLUMN "tk"."species"."charge" IS 'Net charge number.';
COMMENT ON COLUMN "tk"."species"."inchikey" IS 'The resolved standard InChIKey.';

CREATE TABLE "tk"."species_form" (
    "id" uuid NOT NULL,
    "species" uuid NOT NULL,
    "aggregation" uuid NOT NULL,
    "polymorph" text,
    CONSTRAINT "species_form__pk" PRIMARY KEY ("id"),
    CONSTRAINT "species_form__uq__species_aggregation_polymorph" UNIQUE ("species", "aggregation", "polymorph")
);
COMMENT ON TABLE "tk"."species_form" IS 'A species in a state of aggregation and, for a crystalline solid, a polymorph. This is what thermochemical databases call a species or substance, and what reactions and standard-state data are about. Canonical key: species key, aggregation and polymorph.';
COMMENT ON COLUMN "tk"."species_form"."id" IS 'Deterministic identifier of the species_form instance.';
COMMENT ON COLUMN "tk"."species_form"."species" IS 'The chemical identity.';
COMMENT ON COLUMN "tk"."species_form"."aggregation" IS 'The state of aggregation.';
COMMENT ON COLUMN "tk"."species_form"."polymorph" IS 'Polymorph or structure designation for a crystalline form.';

CREATE TABLE "tk"."standard_state" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "kind" "meta"."standard_state_kind" NOT NULL,
    "scale" uuid,
    "pressure_rule" "meta"."pressure_rule" NOT NULL,
    "pressure" "meta"."pressure",
    "solvent" uuid,
    CONSTRAINT "standard_state__pk" PRIMARY KEY ("id"),
    CONSTRAINT "standard_state__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."standard_state" IS 'The state that defines the standard chemical potential used with an activity or a fugacity.';
COMMENT ON COLUMN "tk"."standard_state"."id" IS 'Deterministic identifier of the standard_state instance.';
COMMENT ON COLUMN "tk"."standard_state"."key" IS 'Stable key.';
COMMENT ON COLUMN "tk"."standard_state"."kind" IS 'The kind of state.';
COMMENT ON COLUMN "tk"."standard_state"."scale" IS 'The composition scale of an infinite-dilution or site reference; the basis `not_stated` where the source names none.';
COMMENT ON COLUMN "tk"."standard_state"."pressure_rule" IS 'How its pressure is fixed.';
COMMENT ON COLUMN "tk"."standard_state"."pressure" IS 'The pressure, when fixed.';
COMMENT ON COLUMN "tk"."standard_state"."solvent" IS 'The solvent of an infinite-dilution reference.';

CREATE TABLE "tk"."tabulated_axis" (
    "id" uuid NOT NULL,
    "function" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "axis_type" uuid NOT NULL,
    "points" "meta"."finite_real"[] NOT NULL,
    CONSTRAINT "tabulated_axis__pk" PRIMARY KEY ("id"),
    CONSTRAINT "tabulated_axis__identity" UNIQUE ("function", "ordinal"),
    CONSTRAINT "tabulated_axis__ck__points__no_null" CHECK (array_position("points", NULL) IS NULL),
    CONSTRAINT "tabulated_axis__ck__ordinal_from_one" CHECK ("ordinal" > 0)
);
COMMENT ON TABLE "tk"."tabulated_axis" IS 'One axis of a tabulated function.';
COMMENT ON COLUMN "tk"."tabulated_axis"."id" IS 'Deterministic identifier of the tabulated_axis instance.';
COMMENT ON COLUMN "tk"."tabulated_axis"."function" IS 'The function.';
COMMENT ON COLUMN "tk"."tabulated_axis"."ordinal" IS 'Position of the axis, from one.';
COMMENT ON COLUMN "tk"."tabulated_axis"."axis_type" IS 'Quantity type of the axis.';
COMMENT ON COLUMN "tk"."tabulated_axis"."points" IS 'Axis values in the axis type''s storage unit.';

CREATE TABLE "tk"."tabulated_function" (
    "id" uuid NOT NULL,
    "key" text NOT NULL,
    "interpolation" "meta"."interpolation" NOT NULL,
    "distribution" uuid,
    CONSTRAINT "tabulated_function__pk" PRIMARY KEY ("id"),
    CONSTRAINT "tabulated_function__identity" UNIQUE ("key")
);
COMMENT ON TABLE "tk"."tabulated_function" IS 'A function given as values on a grid, with how to evaluate it between points. It has one or more axes and one or more named series on the same grid. Sigma profiles (three series on one axis), collision-integral tables and pore-size kernels (two axes) are tabulated functions.';
COMMENT ON COLUMN "tk"."tabulated_function"."id" IS 'Deterministic identifier of the tabulated_function instance.';
COMMENT ON COLUMN "tk"."tabulated_function"."key" IS 'Stable key, computed from the owning set, slot and index.';
COMMENT ON COLUMN "tk"."tabulated_function"."interpolation" IS 'How it is evaluated between points.';
COMMENT ON COLUMN "tk"."tabulated_function"."distribution" IS 'What the function is a distribution of, when it is one.';

CREATE TABLE "tk"."tabulated_series" (
    "id" uuid NOT NULL,
    "function" uuid NOT NULL,
    "name" text NOT NULL,
    "value_type" uuid NOT NULL,
    "values" "meta"."finite_real"[] NOT NULL,
    CONSTRAINT "tabulated_series__pk" PRIMARY KEY ("id"),
    CONSTRAINT "tabulated_series__identity" UNIQUE ("function", "name"),
    CONSTRAINT "tabulated_series__ck__values__no_null" CHECK (array_position("values", NULL) IS NULL)
);
COMMENT ON TABLE "tk"."tabulated_series" IS 'One named series of values of a tabulated function, over the full grid of its axes.';
COMMENT ON COLUMN "tk"."tabulated_series"."id" IS 'Deterministic identifier of the tabulated_series instance.';
COMMENT ON COLUMN "tk"."tabulated_series"."function" IS 'The function.';
COMMENT ON COLUMN "tk"."tabulated_series"."name" IS 'Name of the series; `value` when the function has one series.';
COMMENT ON COLUMN "tk"."tabulated_series"."value_type" IS 'Quantity type of the values.';
COMMENT ON COLUMN "tk"."tabulated_series"."values" IS 'Values in the value type''s storage unit, in row-major order over the axes.';

CREATE TABLE "ev"."uncertainty_assessment" (
    "id" uuid NOT NULL,
    "column" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "kind" "meta"."uncertainty_kind" NOT NULL,
    "coverage_factor" "meta"."scalar",
    "confidence_level" "meta"."fraction",
    "evaluator" text,
    "method" text,
    CONSTRAINT "uncertainty_assessment__pk" PRIMARY KEY ("id"),
    CONSTRAINT "uncertainty_assessment__identity" UNIQUE ("column", "ordinal"),
    CONSTRAINT "uncertainty_assessment__ck__ordinal_from_one" CHECK ("ordinal" > 0)
);
COMMENT ON TABLE "ev"."uncertainty_assessment" IS 'One way the uncertainty of the values of a column is assessed: what its magnitudes mean and, where the source states them, the coverage factor, the level of confidence, who assessed it and by what method. A column has as many assessments as its source defines, and the magnitudes of each are stated per value (`datum_uncertainty`) or, for the constant of a constraint column, once (`column_uncertainty`).';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."id" IS 'Deterministic identifier of the uncertainty_assessment instance.';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."column" IS 'The column whose values are assessed.';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."ordinal" IS 'Position among the assessments of the column, from one.';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."kind" IS 'What the magnitudes of this assessment mean.';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."coverage_factor" IS 'Coverage factor of an expanded uncertainty.';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."confidence_level" IS 'Level of confidence of an expanded uncertainty, as a fraction.';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."evaluator" IS 'Who assessed the uncertainty, as the source states it.';
COMMENT ON COLUMN "ev"."uncertainty_assessment"."method" IS 'How it was assessed, as the source states it.';

CREATE TABLE "tk"."unclassified_entity" (
    "id" uuid NOT NULL,
    CONSTRAINT "unclassified_entity__pk" PRIMARY KEY ("id")
);
COMMENT ON TABLE "tk"."unclassified_entity" IS 'An entity whose class its source does not establish; it is never joined across carriers. It is the provisional entity of a source entity of class `undetermined`.';
COMMENT ON COLUMN "tk"."unclassified_entity"."id" IS 'Deterministic identifier of the unclassified_entity instance.';

CREATE TABLE "tk"."validity_region" (
    "id" uuid NOT NULL,
    "record" uuid NOT NULL,
    "kind" "meta"."envelope_kind" NOT NULL,
    "ordinal" bigint NOT NULL,
    CONSTRAINT "validity_region__pk" PRIMARY KEY ("id"),
    CONSTRAINT "validity_region__identity" UNIQUE ("record", "kind", "ordinal"),
    CONSTRAINT "validity_region__ck__ordinal_from_one" CHECK ("ordinal" > 0)
);
COMMENT ON TABLE "tk"."validity_region" IS 'A region of conditions in which a record applies, as its source states it. A region is the conjunction of its clauses; several regions of one kind on one record are alternatives, so the validity of the record is their union. This is scientific applicability: it is not a numerical bound and not a piece interval. The record may be a parameter set, a parameterisation or a model assembly.';
COMMENT ON COLUMN "tk"."validity_region"."id" IS 'Deterministic identifier of the validity_region instance.';
COMMENT ON COLUMN "tk"."validity_region"."record" IS 'The parameter set, parameterisation or model assembly the region is stated for.';
COMMENT ON COLUMN "tk"."validity_region"."kind" IS 'What the region represents.';
COMMENT ON COLUMN "tk"."validity_region"."ordinal" IS 'Position among the regions of this kind on the record, from one.';

CREATE TABLE "param"."vapor_pressure_exp_series_tau__pure" (
    "id" uuid NOT NULL,
    "slot_group" uuid NOT NULL DEFAULT '3e0a0dfd-7fb2-5591-b4ca-58f7b3a0bd3e'::uuid,
    "i" uuid NOT NULL,
    "T_r" "meta"."temperature" NOT NULL,
    "p_r" "meta"."pressure" NOT NULL,
    CONSTRAINT "vapor_pressure_exp_series_tau__pure__pk" PRIMARY KEY ("id"),
    CONSTRAINT "vapor_pressure_exp_series_tau__pure__ck__slot_group" CHECK ("slot_group" = '3e0a0dfd-7fb2-5591-b4ca-58f7b3a0bd3e'::uuid)
);
COMMENT ON TABLE "param"."vapor_pressure_exp_series_tau__pure" IS 'The curve of one fluid.';
COMMENT ON COLUMN "param"."vapor_pressure_exp_series_tau__pure"."id" IS 'Deterministic identifier of the vapor_pressure_exp_series_tau__pure instance.';
COMMENT ON COLUMN "param"."vapor_pressure_exp_series_tau__pure"."slot_group" IS 'The slot group of this table; fixed, and tied to the parameter set row.';
COMMENT ON COLUMN "param"."vapor_pressure_exp_series_tau__pure"."i" IS 'The fluid.';
COMMENT ON COLUMN "param"."vapor_pressure_exp_series_tau__pure"."T_r" IS 'Reducing temperature of the curve; the curve is defined up to it.';
COMMENT ON COLUMN "param"."vapor_pressure_exp_series_tau__pure"."p_r" IS 'Reducing pressure of the curve.';

CREATE TABLE "tk"."accuracy_statement" (
    "id" uuid NOT NULL,
    "record" uuid NOT NULL,
    "observable" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "region" uuid,
    "against" uuid,
    "kind" "meta"."uncertainty_kind" NOT NULL,
    "statistic" "meta"."accuracy_statistic" NOT NULL,
    "magnitude" "meta"."finite_real",
    "relative_magnitude" "meta"."scalar",
    "sample_size" bigint,
    CONSTRAINT "accuracy_statement__pk" PRIMARY KEY ("record", "observable", "ordinal"),
    CONSTRAINT "accuracy_statement__uq__id" UNIQUE ("id"),
    CONSTRAINT "accuracy_statement__ck__ordinal_from_one" CHECK ("ordinal" > 0),
    CONSTRAINT "accuracy_statement__ck__sample_size_positive" CHECK ("sample_size" > 0)
);
COMMENT ON TABLE "tk"."accuracy_statement" IS 'What a source states about the accuracy of one observable a record gives: over a region of the state space or at a stated condition, against evidence or another record, as a bound or a statistic. IAPWS-95 states percentages per region of temperature and pressure; IF97 states consistency tolerances against the IAPWS-95 formulation; a rate rule states the distribution of the logarithm of the rate at a reference temperature. It is what a source claims, not a qualification result.';
COMMENT ON COLUMN "tk"."accuracy_statement"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."accuracy_statement"."record" IS 'The record the statement is about: a parameter set, a parameterisation or a model assembly.';
COMMENT ON COLUMN "tk"."accuracy_statement"."observable" IS 'The output the statement is about.';
COMMENT ON COLUMN "tk"."accuracy_statement"."ordinal" IS 'Position among the statements about this observable of the record, from one.';
COMMENT ON COLUMN "tk"."accuracy_statement"."region" IS 'The region of conditions the statement holds over; a condition such as a reference temperature is a region with a clause that has one point. Absent when the statement is not limited to a region.';
COMMENT ON COLUMN "tk"."accuracy_statement"."against" IS 'The record the deviation is taken against, where the statement is a comparison with another record rather than with evidence.';
COMMENT ON COLUMN "tk"."accuracy_statement"."kind" IS 'What the magnitude means.';
COMMENT ON COLUMN "tk"."accuracy_statement"."statistic" IS 'What statistic of the deviation the magnitude is.';
COMMENT ON COLUMN "tk"."accuracy_statement"."magnitude" IS 'The magnitude of a kind stated in the observable''s unit, in its storage unit.';
COMMENT ON COLUMN "tk"."accuracy_statement"."relative_magnitude" IS 'The magnitude of a kind that is dimensionless: a fraction of the value for a relative kind, the factor f for a multiplicative one.';
COMMENT ON COLUMN "tk"."accuracy_statement"."sample_size" IS 'The number of values the statistic was computed from, where the source states it.';

CREATE TABLE "prov"."attribution" (
    "id" uuid NOT NULL,
    "import_record" uuid NOT NULL,
    "primary" uuid NOT NULL,
    "page" text,
    "table" text,
    "equation" text,
    "figure" text,
    CONSTRAINT "attribution__pk" PRIMARY KEY ("import_record", "primary"),
    CONSTRAINT "attribution__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "prov"."attribution" IS 'The primary source an import record''s content is attributed to, as distinct from the carrier it was read from, with where in the primary work the content is where the carrier says.';
COMMENT ON COLUMN "prov"."attribution"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."attribution"."import_record" IS 'The import record.';
COMMENT ON COLUMN "prov"."attribution"."primary" IS 'The source credited with the content.';
COMMENT ON COLUMN "prov"."attribution"."page" IS 'The page of the primary work the content is on, as the carrier gives it.';
COMMENT ON COLUMN "prov"."attribution"."table" IS 'The table of the primary work the content is in, as the carrier gives it.';
COMMENT ON COLUMN "prov"."attribution"."equation" IS 'The equation of the primary work the content is, as the carrier gives it.';
COMMENT ON COLUMN "prov"."attribution"."figure" IS 'The figure of the primary work the content is in, as the carrier gives it.';

CREATE TABLE "tk"."auxiliary_of" (
    "id" uuid NOT NULL,
    "auxiliary" uuid NOT NULL,
    "target" uuid NOT NULL,
    "kind" "meta"."auxiliary_kind" NOT NULL,
    "max_relative_error" "meta"."scalar",
    CONSTRAINT "auxiliary_of__pk" PRIMARY KEY ("auxiliary", "target"),
    CONSTRAINT "auxiliary_of__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."auxiliary_of" IS 'A parameter set approximates, inverts or bounds a quantity of another model. It is never an independent authority for that quantity; it carries its accuracy claim and points at what it was derived from.';
COMMENT ON COLUMN "tk"."auxiliary_of"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."auxiliary_of"."auxiliary" IS 'The auxiliary parameter set.';
COMMENT ON COLUMN "tk"."auxiliary_of"."target" IS 'The parameter set, parameterisation or model assembly whose quantity it serves.';
COMMENT ON COLUMN "tk"."auxiliary_of"."kind" IS 'How it relates to the target.';
COMMENT ON COLUMN "tk"."auxiliary_of"."max_relative_error" IS 'The largest relative deviation from the target that the source claims.';

CREATE TABLE "qual"."capability" (
    "id" uuid NOT NULL,
    "library" uuid NOT NULL,
    "calculation" uuid NOT NULL,
    "scope" text NOT NULL,
    "evidence" "meta"."capability_evidence" NOT NULL,
    "locator" text,
    CONSTRAINT "capability__pk" PRIMARY KEY ("library", "calculation", "scope"),
    CONSTRAINT "capability__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "qual"."capability" IS 'A library release offers a calculation. The claim records how it was established.';
COMMENT ON COLUMN "qual"."capability"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "qual"."capability"."library" IS 'The library release.';
COMMENT ON COLUMN "qual"."capability"."calculation" IS 'The calculation offered.';
COMMENT ON COLUMN "qual"."capability"."scope" IS 'The model families or phase kinds the claim is limited to; empty when unrestricted.';
COMMENT ON COLUMN "qual"."capability"."evidence" IS 'How the claim was established.';
COMMENT ON COLUMN "qual"."capability"."locator" IS 'Where in the documentation or source the capability is found.';

CREATE TABLE "prov"."citation" (
    "id" uuid NOT NULL,
    "carrier" uuid NOT NULL,
    "local_key" text NOT NULL,
    "publication" uuid NOT NULL,
    "year" bigint,
    "citation" text,
    CONSTRAINT "citation__pk" PRIMARY KEY ("carrier", "local_key"),
    CONSTRAINT "citation__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "prov"."citation" IS 'The publication a carrier''s own citation key denotes, with what that carrier says about it. Several carriers citing one work give one publication and one row each.';
COMMENT ON COLUMN "prov"."citation"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."citation"."carrier" IS 'The carrier that cites the work.';
COMMENT ON COLUMN "prov"."citation"."local_key" IS 'The carrier''s citation key, verbatim.';
COMMENT ON COLUMN "prov"."citation"."publication" IS 'The work the key denotes.';
COMMENT ON COLUMN "prov"."citation"."year" IS 'Year of publication as the carrier states it.';
COMMENT ON COLUMN "prov"."citation"."citation" IS 'Bibliographic citation as the carrier gives it.';

CREATE TABLE "ev"."column_uncertainty" (
    "id" uuid NOT NULL,
    "assessment" uuid NOT NULL,
    "minus" "meta"."finite_real",
    "plus" "meta"."finite_real",
    "relative_minus" "meta"."scalar",
    "relative_plus" "meta"."scalar",
    CONSTRAINT "column_uncertainty__pk" PRIMARY KEY ("assessment"),
    CONSTRAINT "column_uncertainty__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "ev"."column_uncertainty" IS 'The magnitudes of one uncertainty assessment for the constant of a constraint column, stated as `datum_uncertainty` states them for a value.';
COMMENT ON COLUMN "ev"."column_uncertainty"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "ev"."column_uncertainty"."assessment" IS 'The assessment.';
COMMENT ON COLUMN "ev"."column_uncertainty"."minus" IS 'The magnitude below the constant, in the column observable''s storage unit.';
COMMENT ON COLUMN "ev"."column_uncertainty"."plus" IS 'The magnitude above the constant, in the column observable''s storage unit.';
COMMENT ON COLUMN "ev"."column_uncertainty"."relative_minus" IS 'The relative magnitude below the constant, as a fraction of it, or the factor f of a multiplicative kind.';
COMMENT ON COLUMN "ev"."column_uncertainty"."relative_plus" IS 'The relative magnitude above the constant, as a fraction of it, or the factor f of a multiplicative kind.';

CREATE TABLE "tk"."composition" (
    "id" uuid NOT NULL,
    "entity" uuid NOT NULL,
    "quantity" uuid NOT NULL,
    "value" "meta"."count" NOT NULL,
    CONSTRAINT "composition__pk" PRIMARY KEY ("entity", "quantity"),
    CONSTRAINT "composition__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."composition" IS 'How much of a conserved quantity one formula unit of an entity contains: atoms of an element, units of charge, or sites.';
COMMENT ON COLUMN "tk"."composition"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."composition"."entity" IS 'The entity whose formula this is.';
COMMENT ON COLUMN "tk"."composition"."quantity" IS 'The conserved quantity.';
COMMENT ON COLUMN "tk"."composition"."value" IS 'The value.';

CREATE TABLE "tk"."constituent_array_member" (
    "id" uuid NOT NULL,
    "array" uuid NOT NULL,
    "site_class" uuid NOT NULL,
    "position" bigint NOT NULL,
    "species" uuid NOT NULL,
    CONSTRAINT "constituent_array_member__pk" PRIMARY KEY ("array", "site_class", "position"),
    CONSTRAINT "constituent_array_member__uq__id" UNIQUE ("id"),
    CONSTRAINT "constituent_array_member__ck__position_from_one" CHECK ("position" > 0)
);
COMMENT ON TABLE "tk"."constituent_array_member" IS 'A species an array places on a site class.';
COMMENT ON COLUMN "tk"."constituent_array_member"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."constituent_array_member"."array" IS 'The array.';
COMMENT ON COLUMN "tk"."constituent_array_member"."site_class" IS 'A site class of the array''s phase.';
COMMENT ON COLUMN "tk"."constituent_array_member"."position" IS 'Position of the species among those the array places on this site class, from one.';
COMMENT ON COLUMN "tk"."constituent_array_member"."species" IS 'The species at that position.';

CREATE TABLE "tk"."convention_standard_state" (
    "id" uuid NOT NULL,
    "convention_set" uuid NOT NULL,
    "member_role" uuid NOT NULL,
    "value" uuid NOT NULL,
    CONSTRAINT "convention_standard_state__pk" PRIMARY KEY ("convention_set", "member_role"),
    CONSTRAINT "convention_standard_state__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."convention_standard_state" IS 'The standard state a convention set gives for each member role its chemical systems use. A reaction participant may still state its own.';
COMMENT ON COLUMN "tk"."convention_standard_state"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."convention_standard_state"."convention_set" IS 'The convention set.';
COMMENT ON COLUMN "tk"."convention_standard_state"."member_role" IS 'The part a species form plays in a chemical system that the standard state applies to.';
COMMENT ON COLUMN "tk"."convention_standard_state"."value" IS 'The value.';

CREATE TABLE "ev"."dataset_verifies" (
    "id" uuid NOT NULL,
    "dataset" uuid NOT NULL,
    "target" uuid NOT NULL,
    CONSTRAINT "dataset_verifies__pk" PRIMARY KEY ("dataset", "target"),
    CONSTRAINT "dataset_verifies__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "ev"."dataset_verifies" IS 'A record whose implementation a verification dataset checks. The values of a check table depend on both the formulation and the coefficients it was computed with, so a dataset names the model assembly and the parameterisation it verifies, each by a row (a published test value of the GERG-2008 and DETAIL assemblies, of the IAPWS-IF97 assembly with the coefficient set of the release, of a COSMO-SAC parameterisation together with the profile set). Only verification datasets state one.';
COMMENT ON COLUMN "ev"."dataset_verifies"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "ev"."dataset_verifies"."dataset" IS 'The verification dataset.';
COMMENT ON COLUMN "ev"."dataset_verifies"."target" IS 'The model assembly or parameterization whose implementation the values check.';

CREATE TABLE "ev"."datum" (
    "id" uuid NOT NULL,
    "point" uuid NOT NULL,
    "column" uuid NOT NULL,
    "state" "meta"."datum_state" NOT NULL,
    "value" "meta"."finite_real",
    "digits" bigint,
    CONSTRAINT "datum__pk" PRIMARY KEY ("point", "column"),
    CONSTRAINT "datum__uq__id" UNIQUE ("id"),
    CONSTRAINT "datum__ck__value_matches_state" CHECK (("value" IS NOT NULL) = ("state"::text IN ('known', 'censored_below', 'censored_above')))
);
COMMENT ON TABLE "ev"."datum" IS 'The value a point has in a column, or why it has none. The uncertainties of the value are `datum_uncertainty` rows.';
COMMENT ON COLUMN "ev"."datum"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "ev"."datum"."point" IS 'The point.';
COMMENT ON COLUMN "ev"."datum"."column" IS 'The column.';
COMMENT ON COLUMN "ev"."datum"."state" IS 'Whether a value is reported.';
COMMENT ON COLUMN "ev"."datum"."value" IS 'The value, or the limit when censored, in the column observable''s storage unit.';
COMMENT ON COLUMN "ev"."datum"."digits" IS 'Number of significant digits the source reports.';

CREATE TABLE "ev"."datum_uncertainty" (
    "id" uuid NOT NULL,
    "point" uuid NOT NULL,
    "assessment" uuid NOT NULL,
    "minus" "meta"."finite_real",
    "plus" "meta"."finite_real",
    "relative_minus" "meta"."scalar",
    "relative_plus" "meta"."scalar",
    CONSTRAINT "datum_uncertainty__pk" PRIMARY KEY ("point", "assessment"),
    CONSTRAINT "datum_uncertainty__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "ev"."datum_uncertainty" IS 'The magnitudes of one uncertainty assessment for the value of one point. Both sides are stated: a symmetric uncertainty has equal `minus` and `plus`. A kind stated in the unit of the quantity has `minus` and `plus`; a relative kind, and a multiplicative one (the factor f, in both columns), has `relative_minus` and `relative_plus`.';
COMMENT ON COLUMN "ev"."datum_uncertainty"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "ev"."datum_uncertainty"."point" IS 'The point.';
COMMENT ON COLUMN "ev"."datum_uncertainty"."assessment" IS 'The assessment.';
COMMENT ON COLUMN "ev"."datum_uncertainty"."minus" IS 'The magnitude below the value, in the column observable''s storage unit.';
COMMENT ON COLUMN "ev"."datum_uncertainty"."plus" IS 'The magnitude above the value, in the column observable''s storage unit.';
COMMENT ON COLUMN "ev"."datum_uncertainty"."relative_minus" IS 'The relative magnitude below the value, as a fraction of it, or the factor f of a multiplicative kind.';
COMMENT ON COLUMN "ev"."datum_uncertainty"."relative_plus" IS 'The relative magnitude above the value, as a fraction of it, or the factor f of a multiplicative kind.';

CREATE TABLE "tk"."dependency" (
    "id" uuid NOT NULL,
    "dependent" uuid NOT NULL,
    "prerequisite" uuid NOT NULL,
    "kind" "meta"."dependency_kind" NOT NULL,
    CONSTRAINT "dependency__pk" PRIMARY KEY ("dependent", "prerequisite"),
    CONSTRAINT "dependency__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."dependency" IS 'One record was obtained assuming another, and is valid only with it.';
COMMENT ON COLUMN "tk"."dependency"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."dependency"."dependent" IS 'The record that depends.';
COMMENT ON COLUMN "tk"."dependency"."prerequisite" IS 'The record it assumes: a parameter set, a parameterisation or a model assembly.';
COMMENT ON COLUMN "tk"."dependency"."kind" IS 'How it depends.';

CREATE TABLE "prov"."derivation_input" (
    "id" uuid NOT NULL,
    "derivation" uuid NOT NULL,
    "record" uuid NOT NULL,
    "weight" "meta"."scalar",
    "excluded" boolean NOT NULL DEFAULT false,
    CONSTRAINT "derivation_input__pk" PRIMARY KEY ("derivation", "record"),
    CONSTRAINT "derivation_input__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "prov"."derivation_input" IS 'A record a derivation used.';
COMMENT ON COLUMN "prov"."derivation_input"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."derivation_input"."derivation" IS 'The derivation.';
COMMENT ON COLUMN "prov"."derivation_input"."record" IS 'A record it consumed.';
COMMENT ON COLUMN "prov"."derivation_input"."weight" IS 'Weight given to this input, where the derivation states one.';
COMMENT ON COLUMN "prov"."derivation_input"."excluded" IS 'True when the input was considered and explicitly excluded.';

CREATE TABLE "prov"."derivation_output" (
    "id" uuid NOT NULL,
    "derivation" uuid NOT NULL,
    "record" uuid NOT NULL,
    CONSTRAINT "derivation_output__pk" PRIMARY KEY ("derivation", "record"),
    CONSTRAINT "derivation_output__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "prov"."derivation_output" IS 'A record a derivation produced.';
COMMENT ON COLUMN "prov"."derivation_output"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."derivation_output"."derivation" IS 'The derivation.';
COMMENT ON COLUMN "prov"."derivation_output"."record" IS 'A record it produced.';

CREATE TABLE "tk"."disordered_partner" (
    "id" uuid NOT NULL,
    "ordered" uuid NOT NULL,
    "disordered" uuid NOT NULL,
    "never_disorder" boolean NOT NULL,
    CONSTRAINT "disordered_partner__pk" PRIMARY KEY ("ordered", "disordered"),
    CONSTRAINT "disordered_partner__uq__id" UNIQUE ("id"),
    CONSTRAINT "disordered_partner__ck__diagonal" CHECK ("ordered" <> "disordered")
);
COMMENT ON TABLE "tk"."disordered_partner" IS 'The disordered phase an ordered phase is the ordered form of: a sublattice model of an ordered phase is the disordered phase''s model plus an ordering contribution, so the ordered phase names its partner. The pair is directed and the two phases differ.';
COMMENT ON COLUMN "tk"."disordered_partner"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."disordered_partner"."ordered" IS 'The ordered phase.';
COMMENT ON COLUMN "tk"."disordered_partner"."disordered" IS 'Its disordered partner.';
COMMENT ON COLUMN "tk"."disordered_partner"."never_disorder" IS 'True when the source switches the partition off: the ordered phase never disorders, and its energy has no disordered part, which changes the equation.';

CREATE TABLE "tk"."element_reference" (
    "id" uuid NOT NULL,
    "reference" uuid NOT NULL,
    "element" uuid NOT NULL,
    "value" uuid NOT NULL,
    CONSTRAINT "element_reference__pk" PRIMARY KEY ("reference", "element"),
    CONSTRAINT "element_reference__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."element_reference" IS 'The reference form of an element under an energy reference. Formation and stable-element datums name one per element they cover.';
COMMENT ON COLUMN "tk"."element_reference"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."element_reference"."reference" IS 'The energy reference.';
COMMENT ON COLUMN "tk"."element_reference"."element" IS 'The element.';
COMMENT ON COLUMN "tk"."element_reference"."value" IS 'The value.';

CREATE TABLE "tk"."entity_model" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "entity" uuid NOT NULL,
    "value" uuid NOT NULL,
    CONSTRAINT "entity_model__pk" PRIMARY KEY ("parameterization", "entity"),
    CONSTRAINT "entity_model__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."entity_model" IS 'The model assembly that describes one entity under a parameterisation, for bodies of data that assemble a model per substance (a standard-state model built from an equation of state, a temperature correction and a pressure correction, with a solvent model).';
COMMENT ON COLUMN "tk"."entity_model"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."entity_model"."parameterization" IS 'The parameterisation.';
COMMENT ON COLUMN "tk"."entity_model"."entity" IS 'The entity described.';
COMMENT ON COLUMN "tk"."entity_model"."value" IS 'The assembly.';

CREATE TABLE "prov"."equivalence_assessment" (
    "id" uuid NOT NULL,
    "a" uuid NOT NULL,
    "b" uuid NOT NULL,
    "level" "meta"."equivalence_level" NOT NULL,
    "conversion" uuid,
    CONSTRAINT "equivalence_assessment__pk" PRIMARY KEY ("a", "b"),
    CONSTRAINT "equivalence_assessment__uq__id" UNIQUE ("id"),
    CONSTRAINT "equivalence_assessment__ck__conversion_iff_under_conversion" CHECK (("conversion" IS NOT NULL) = ("level"::text IN ('equal_under_conversion'))),
    CONSTRAINT "equivalence_assessment__ck__canonical" CHECK ("a" <= "b"),
    CONSTRAINT "equivalence_assessment__ck__diagonal" CHECK ("a" <> "b")
);
COMMENT ON TABLE "prov"."equivalence_assessment" IS 'A derived statement that two records assert the same primary fact. It is never an identity and can be rebuilt.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."a" IS 'One record.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."b" IS 'The other record.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."level" IS 'How the two compare.';
COMMENT ON COLUMN "prov"."equivalence_assessment"."conversion" IS 'The conversion under which the two agree.';

CREATE TABLE "prov"."fit_correlation" (
    "id" uuid NOT NULL,
    "fit" uuid NOT NULL,
    "a" bigint NOT NULL,
    "b" bigint NOT NULL,
    "coefficient" "meta"."scalar" NOT NULL,
    CONSTRAINT "fit_correlation__pk" PRIMARY KEY ("fit", "a", "b"),
    CONSTRAINT "fit_correlation__uq__id" UNIQUE ("id"),
    CONSTRAINT "fit_correlation__ck__a_from_one" CHECK ("a" > 0),
    CONSTRAINT "fit_correlation__ck__b_from_one" CHECK ("b" > 0),
    CONSTRAINT "fit_correlation__ck__coefficient_in_range" CHECK ("coefficient" >= -1.0 AND "coefficient" <= 1.0),
    CONSTRAINT "fit_correlation__ck__canonical" CHECK ("a" <= "b"),
    CONSTRAINT "fit_correlation__ck__diagonal" CHECK ("a" <> "b")
);
COMMENT ON TABLE "prov"."fit_correlation" IS 'The correlation of the estimates of two free parameters of a fit, which together with their standard uncertainties gives the covariance.';
COMMENT ON COLUMN "prov"."fit_correlation"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."fit_correlation"."fit" IS 'The fit.';
COMMENT ON COLUMN "prov"."fit_correlation"."a" IS 'Position of one free parameter in the fit''s parameter vector.';
COMMENT ON COLUMN "prov"."fit_correlation"."b" IS 'Position of the other free parameter.';
COMMENT ON COLUMN "prov"."fit_correlation"."coefficient" IS 'The correlation coefficient.';

CREATE TABLE "prov"."fit_free_parameter" (
    "id" uuid NOT NULL,
    "fit" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "record" uuid NOT NULL,
    "slot" uuid,
    "standard_uncertainty" "meta"."finite_real",
    "index_key" text NOT NULL DEFAULT '',
    CONSTRAINT "fit_free_parameter__pk" PRIMARY KEY ("fit", "ordinal"),
    CONSTRAINT "fit_free_parameter__uq__id" UNIQUE ("id"),
    CONSTRAINT "fit_free_parameter__ck__ordinal_from_one" CHECK ("ordinal" > 0)
);
COMMENT ON TABLE "prov"."fit_free_parameter" IS 'A parameter a fit was free to vary, addressed down to the coefficient. Uncertainties and correlations are stated over these, by position.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."fit" IS 'The fit.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."ordinal" IS 'Position of the parameter in the fit''s parameter vector, from one.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."record" IS 'The parameter set or entity record the parameter belongs to.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."slot" IS 'The slot, when the record is a parameter set.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."standard_uncertainty" IS 'The standard uncertainty of the fitted value, in the slot''s storage unit.';
COMMENT ON COLUMN "prov"."fit_free_parameter"."index_key" IS 'Canonical encoding of the family index, empty for a slot outside any family.';

CREATE TABLE "tk"."group_bond_count" (
    "id" uuid NOT NULL,
    "assignment" uuid NOT NULL,
    "first" uuid NOT NULL,
    "second" uuid NOT NULL,
    "value" "meta"."count" NOT NULL,
    CONSTRAINT "group_bond_count__pk" PRIMARY KEY ("assignment", "first", "second"),
    CONSTRAINT "group_bond_count__uq__id" UNIQUE ("id"),
    CONSTRAINT "group_bond_count__ck__canonical" CHECK ("first" <= "second")
);
COMMENT ON TABLE "tk"."group_bond_count" IS 'How many bonds join two groups within one decomposition: heterosegmented models need the bonds between the groups of one molecule. The pair is unordered and may name one group twice, for a bond between two groups of the same kind.';
COMMENT ON COLUMN "tk"."group_bond_count"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."group_bond_count"."assignment" IS 'The assignment.';
COMMENT ON COLUMN "tk"."group_bond_count"."first" IS 'One group of the bond.';
COMMENT ON COLUMN "tk"."group_bond_count"."second" IS 'The other group of the bond.';
COMMENT ON COLUMN "tk"."group_bond_count"."value" IS 'The number of bonds between the two groups.';

CREATE TABLE "tk"."group_count" (
    "id" uuid NOT NULL,
    "assignment" uuid NOT NULL,
    "group" uuid NOT NULL,
    "value" "meta"."count" NOT NULL,
    CONSTRAINT "group_count__pk" PRIMARY KEY ("assignment", "group"),
    CONSTRAINT "group_count__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."group_count" IS 'How many times a group occurs in an assignment.';
COMMENT ON COLUMN "tk"."group_count"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."group_count"."assignment" IS 'The assignment.';
COMMENT ON COLUMN "tk"."group_count"."group" IS 'A group.';
COMMENT ON COLUMN "tk"."group_count"."value" IS 'The value.';

CREATE TABLE "tk"."mixture_component" (
    "id" uuid NOT NULL,
    "mixture" uuid NOT NULL,
    "component" uuid NOT NULL,
    "value" "meta"."fraction" NOT NULL,
    CONSTRAINT "mixture_component__pk" PRIMARY KEY ("mixture", "component"),
    CONSTRAINT "mixture_component__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."mixture_component" IS 'The fraction of a component in a defined mixture.';
COMMENT ON COLUMN "tk"."mixture_component"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."mixture_component"."mixture" IS 'The mixture.';
COMMENT ON COLUMN "tk"."mixture_component"."component" IS 'A component.';
COMMENT ON COLUMN "tk"."mixture_component"."value" IS 'The value.';

CREATE TABLE "tk"."phase_model" (
    "id" uuid NOT NULL,
    "phase" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "value" uuid NOT NULL,
    CONSTRAINT "phase_model__pk" PRIMARY KEY ("phase", "parameterization"),
    CONSTRAINT "phase_model__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."phase_model" IS 'The model assembly that describes a phase definition. One equation of state may describe several phases.';
COMMENT ON COLUMN "tk"."phase_model"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."phase_model"."phase" IS 'The phase definition.';
COMMENT ON COLUMN "tk"."phase_model"."parameterization" IS 'The parameterisation under which this model describes the phase.';
COMMENT ON COLUMN "tk"."phase_model"."value" IS 'The value.';

CREATE TABLE "tk"."policy_default" (
    "id" uuid NOT NULL,
    "policy" uuid NOT NULL,
    "slot" uuid NOT NULL,
    "state" "meta"."value_state" NOT NULL,
    "value" "meta"."finite_real",
    CONSTRAINT "policy_default__pk" PRIMARY KEY ("policy", "slot"),
    CONSTRAINT "policy_default__uq__id" UNIQUE ("id"),
    CONSTRAINT "policy_default__ck__value_matches_state" CHECK (("value" IS NOT NULL) = ("state"::text IN ('known')))
);
COMMENT ON TABLE "tk"."policy_default" IS 'The default a selection policy states for one slot: what a set that leaves the slot at its stated default (value state `stated_default`) takes under this policy, and what an unasserted subject takes when the policy supplies stated defaults. NRTL''s alpha of 0.3, a temperature coefficient read as zero when absent and a volume translation of zero are such defaults. A default is stated as a value, or as the slot having no meaning.';
COMMENT ON COLUMN "tk"."policy_default"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."policy_default"."policy" IS 'The policy.';
COMMENT ON COLUMN "tk"."policy_default"."slot" IS 'The slot the default is for.';
COMMENT ON COLUMN "tk"."policy_default"."state" IS 'The state the default is: known, or not applicable.';
COMMENT ON COLUMN "tk"."policy_default"."value" IS 'The default value, in the slot''s storage unit; present exactly when the state is known.';

CREATE TABLE "tk"."policy_override" (
    "id" uuid NOT NULL,
    "policy" uuid NOT NULL,
    "parameter_set" uuid NOT NULL,
    CONSTRAINT "policy_override__pk" PRIMARY KEY ("policy", "parameter_set"),
    CONSTRAINT "policy_override__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."policy_override" IS 'A specific set a policy selects regardless of precedence.';
COMMENT ON COLUMN "tk"."policy_override"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."policy_override"."policy" IS 'The policy.';
COMMENT ON COLUMN "tk"."policy_override"."parameter_set" IS 'The set selected for its slot group and subject.';

CREATE TABLE "tk"."policy_precedence" (
    "id" uuid NOT NULL,
    "policy" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "value" bigint NOT NULL,
    CONSTRAINT "policy_precedence__pk" PRIMARY KEY ("policy", "parameterization"),
    CONSTRAINT "policy_precedence__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."policy_precedence" IS 'The rank of a parameterisation within a selection policy; lower ranks are preferred.';
COMMENT ON COLUMN "tk"."policy_precedence"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."policy_precedence"."policy" IS 'The policy.';
COMMENT ON COLUMN "tk"."policy_precedence"."parameterization" IS 'A parameterisation it may select from.';
COMMENT ON COLUMN "tk"."policy_precedence"."value" IS 'The value.';

CREATE TABLE "tk"."purification_step" (
    "id" uuid NOT NULL,
    "sample" uuid NOT NULL,
    "step" bigint NOT NULL,
    "method" uuid,
    "method_text" text,
    CONSTRAINT "purification_step__pk" PRIMARY KEY ("sample", "step"),
    CONSTRAINT "purification_step__uq__id" UNIQUE ("id"),
    CONSTRAINT "purification_step__ck__step_from_one" CHECK ("step" > 0),
    CONSTRAINT "purification_step__ck__one_method" CHECK (num_nonnulls("method", "method_text") = 1)
);
COMMENT ON TABLE "tk"."purification_step" IS 'One step of the purification history of a sample, in the order the source lists them.';
COMMENT ON COLUMN "tk"."purification_step"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."purification_step"."sample" IS 'The sample.';
COMMENT ON COLUMN "tk"."purification_step"."step" IS 'Position in the purification history, from one.';
COMMENT ON COLUMN "tk"."purification_step"."method" IS 'The purification method, where the source names one of a listed vocabulary.';
COMMENT ON COLUMN "tk"."purification_step"."method_text" IS 'The method as free text, where the source gives none of a listed vocabulary.';

CREATE TABLE "tk"."purity_statement" (
    "id" uuid NOT NULL,
    "sample" uuid NOT NULL,
    "ordinal" bigint NOT NULL,
    "basis" "meta"."purity_basis" NOT NULL,
    "value" "meta"."fraction",
    "digits" bigint,
    "method" uuid,
    "method_text" text,
    "impurity" uuid,
    CONSTRAINT "purity_statement__pk" PRIMARY KEY ("sample", "ordinal"),
    CONSTRAINT "purity_statement__uq__id" UNIQUE ("id"),
    CONSTRAINT "purity_statement__ck__ordinal_from_one" CHECK ("ordinal" > 0)
);
COMMENT ON TABLE "tk"."purity_statement" IS 'One statement of the purity of a sample: a purity value on a basis with its significant digits and the analytical method, or the content of one impurity such as water or halide. A sample has as many as its source states, in several bases and after several purification steps.';
COMMENT ON COLUMN "tk"."purity_statement"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."purity_statement"."sample" IS 'The sample.';
COMMENT ON COLUMN "tk"."purity_statement"."ordinal" IS 'Position among the statements about the sample, from one.';
COMMENT ON COLUMN "tk"."purity_statement"."basis" IS 'The basis of the value.';
COMMENT ON COLUMN "tk"."purity_statement"."value" IS 'The stated fraction, where the source gives a value.';
COMMENT ON COLUMN "tk"."purity_statement"."digits" IS 'The number of significant digits the source reports.';
COMMENT ON COLUMN "tk"."purity_statement"."method" IS 'The analytical method, where the source names one of a listed vocabulary.';
COMMENT ON COLUMN "tk"."purity_statement"."method_text" IS 'The analytical method as free text, where the source gives none of a listed vocabulary.';
COMMENT ON COLUMN "tk"."purity_statement"."impurity" IS 'The impurity the statement is the content of, such as water or a halide. Absent when the statement is a purity.';

CREATE TABLE "tk"."reaction_order" (
    "id" uuid NOT NULL,
    "reaction" uuid NOT NULL,
    "form" uuid NOT NULL,
    "value" "meta"."scalar" NOT NULL,
    CONSTRAINT "reaction_order__pk" PRIMARY KEY ("reaction", "form"),
    CONSTRAINT "reaction_order__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."reaction_order" IS 'An explicit forward reaction order of one species form, which need not be an integer and need not be a reactant. Where no row states a species'' order, a reactant''s order is its stoichiometric coefficient and any other species'' order is zero. The orders fix the dimension of a rate constant (`RateConstant`).';
COMMENT ON COLUMN "tk"."reaction_order"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."reaction_order"."reaction" IS 'The reaction.';
COMMENT ON COLUMN "tk"."reaction_order"."form" IS 'The species form the order is stated for.';
COMMENT ON COLUMN "tk"."reaction_order"."value" IS 'The order with respect to the species form.';

CREATE TABLE "tk"."reaction_participant" (
    "id" uuid NOT NULL,
    "reaction" uuid NOT NULL,
    "form" uuid NOT NULL,
    "coefficient" "meta"."count" NOT NULL,
    "standard_state" uuid,
    CONSTRAINT "reaction_participant__pk" PRIMARY KEY ("reaction", "form"),
    CONSTRAINT "reaction_participant__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."reaction_participant" IS 'A species form taking part in a reaction. Coefficients are negative for reactants and positive for products.';
COMMENT ON COLUMN "tk"."reaction_participant"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."reaction_participant"."reaction" IS 'The reaction.';
COMMENT ON COLUMN "tk"."reaction_participant"."form" IS 'A participant.';
COMMENT ON COLUMN "tk"."reaction_participant"."coefficient" IS 'Signed stoichiometric coefficient.';
COMMENT ON COLUMN "tk"."reaction_participant"."standard_state" IS 'The standard state the participant''s activity is referred to.';

CREATE TABLE "prov"."record_origin" (
    "id" uuid NOT NULL,
    "record" uuid NOT NULL,
    "import_record" uuid NOT NULL,
    "role" "meta"."origin_role" NOT NULL,
    CONSTRAINT "record_origin__pk" PRIMARY KEY ("record", "import_record"),
    CONSTRAINT "record_origin__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "prov"."record_origin" IS 'A canonical record was produced from an import record. One source row may yield several records, and an entity may be asserted by many import records.';
COMMENT ON COLUMN "prov"."record_origin"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "prov"."record_origin"."record" IS 'The canonical record.';
COMMENT ON COLUMN "prov"."record_origin"."import_record" IS 'The import record it came from.';
COMMENT ON COLUMN "prov"."record_origin"."role" IS 'How the carrier presents the content.';

CREATE TABLE "tk"."repeat_unit" (
    "id" uuid NOT NULL,
    "polymer" uuid NOT NULL,
    "unit" uuid NOT NULL,
    "value" "meta"."fraction" NOT NULL,
    CONSTRAINT "repeat_unit__pk" PRIMARY KEY ("polymer", "unit"),
    CONSTRAINT "repeat_unit__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."repeat_unit" IS 'A species that is a repeat unit of a polymer type.';
COMMENT ON COLUMN "tk"."repeat_unit"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."repeat_unit"."polymer" IS 'The polymer type.';
COMMENT ON COLUMN "tk"."repeat_unit"."unit" IS 'A repeat unit.';
COMMENT ON COLUMN "tk"."repeat_unit"."value" IS 'The value.';

CREATE TABLE "tk"."resolution_candidate" (
    "id" uuid NOT NULL,
    "source_entity" uuid NOT NULL,
    "candidate" uuid NOT NULL,
    CONSTRAINT "resolution_candidate__pk" PRIMARY KEY ("source_entity", "candidate"),
    CONSTRAINT "resolution_candidate__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."resolution_candidate" IS 'A canonical entity that remained a candidate for an ambiguous source entity.';
COMMENT ON COLUMN "tk"."resolution_candidate"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."resolution_candidate"."source_entity" IS 'The ambiguous source entity.';
COMMENT ON COLUMN "tk"."resolution_candidate"."candidate" IS 'A candidate.';

CREATE TABLE "qual"."run_parameter_set" (
    "id" uuid NOT NULL,
    "run" uuid NOT NULL,
    "parameter_set" uuid NOT NULL,
    CONSTRAINT "run_parameter_set__pk" PRIMARY KEY ("run", "parameter_set"),
    CONSTRAINT "run_parameter_set__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "qual"."run_parameter_set" IS 'A parameter set a qualification run evaluated.';
COMMENT ON COLUMN "qual"."run_parameter_set"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "qual"."run_parameter_set"."run" IS 'The run.';
COMMENT ON COLUMN "qual"."run_parameter_set"."parameter_set" IS 'A set it evaluated.';

CREATE TABLE "tk"."site_equivalence" (
    "id" uuid NOT NULL,
    "a" uuid NOT NULL,
    "b" uuid NOT NULL,
    CONSTRAINT "site_equivalence__pk" PRIMARY KEY ("a", "b"),
    CONSTRAINT "site_equivalence__uq__id" UNIQUE ("id"),
    CONSTRAINT "site_equivalence__ck__canonical" CHECK ("a" <= "b"),
    CONSTRAINT "site_equivalence__ck__diagonal" CHECK ("a" <> "b")
);
COMMENT ON TABLE "tk"."site_equivalence" IS 'Two site classes that are equivalent under permutation, so parameters are unchanged when their occupants are exchanged.';
COMMENT ON COLUMN "tk"."site_equivalence"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."site_equivalence"."a" IS 'One site class.';
COMMENT ON COLUMN "tk"."site_equivalence"."b" IS 'An equivalent site class.';

CREATE TABLE "tk"."site_occupant" (
    "id" uuid NOT NULL,
    "site_class" uuid NOT NULL,
    "occupant" uuid NOT NULL,
    CONSTRAINT "site_occupant__pk" PRIMARY KEY ("site_class", "occupant"),
    CONSTRAINT "site_occupant__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."site_occupant" IS 'A species that may occupy a site class. A vacancy is a species.';
COMMENT ON COLUMN "tk"."site_occupant"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."site_occupant"."site_class" IS 'The site class.';
COMMENT ON COLUMN "tk"."site_occupant"."occupant" IS 'An admissible occupant.';

CREATE TABLE "tk"."snapshot_selection" (
    "id" uuid NOT NULL,
    "snapshot" uuid NOT NULL,
    "parameter_set" uuid NOT NULL,
    CONSTRAINT "snapshot_selection__pk" PRIMARY KEY ("snapshot", "parameter_set"),
    CONSTRAINT "snapshot_selection__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."snapshot_selection" IS 'A parameter set a snapshot selected.';
COMMENT ON COLUMN "tk"."snapshot_selection"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."snapshot_selection"."snapshot" IS 'The snapshot.';
COMMENT ON COLUMN "tk"."snapshot_selection"."parameter_set" IS 'A selected set.';

CREATE TABLE "tk"."speciation_coefficient" (
    "id" uuid NOT NULL,
    "map" uuid NOT NULL,
    "apparent" uuid NOT NULL,
    "true_form" uuid NOT NULL,
    "value" "meta"."count" NOT NULL,
    CONSTRAINT "speciation_coefficient__pk" PRIMARY KEY ("map", "apparent", "true_form"),
    CONSTRAINT "speciation_coefficient__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."speciation_coefficient" IS 'How much of a true species one unit of an apparent entity contributes, for an exact linear map.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."map" IS 'The map.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."apparent" IS 'The apparent entity.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."true_form" IS 'A true species form.';
COMMENT ON COLUMN "tk"."speciation_coefficient"."value" IS 'The value.';

CREATE TABLE "tk"."subject_subform_choice" (
    "id" uuid NOT NULL,
    "parameterization" uuid NOT NULL,
    "slot" uuid NOT NULL,
    "subject_key" text NOT NULL,
    "ordinal" bigint NOT NULL,
    "form" uuid NOT NULL,
    "source_parameterization" uuid,
    CONSTRAINT "subject_subform_choice__pk" PRIMARY KEY ("parameterization", "slot", "subject_key", "ordinal"),
    CONSTRAINT "subject_subform_choice__uq__id" UNIQUE ("id"),
    CONSTRAINT "subject_subform_choice__ck__ordinal_from_one" CHECK ("ordinal" > 0)
);
COMMENT ON TABLE "tk"."subject_subform_choice" IS 'Which form fills a sub-form slot for one subject under a parameterisation: the form chosen for each pair, component or phase when a model puts a different form in the slot for each. A slot with multiplicity many has several choices, numbered from one.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."parameterization" IS 'The parameterisation the choice is made in.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."slot" IS 'The sub-form slot.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."subject_key" IS 'Canonical encoding of the subjects the choice is for, in the role order of the contract the slot accepts, as for a parameter set.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."ordinal" IS 'Position among the choices of a slot with multiplicity many, from one; one otherwise.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."form" IS 'The form chosen.';
COMMENT ON COLUMN "tk"."subject_subform_choice"."source_parameterization" IS 'The parameterisation that holds the chosen form''s parameter sets, when it is not the one the choice is made in.';

CREATE TABLE "tk"."supersedes" (
    "id" uuid NOT NULL,
    "newer" uuid NOT NULL,
    "older" uuid NOT NULL,
    CONSTRAINT "supersedes__pk" PRIMARY KEY ("newer", "older"),
    CONSTRAINT "supersedes__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."supersedes" IS 'A later parameterisation replaces an earlier one; the earlier one remains.';
COMMENT ON COLUMN "tk"."supersedes"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."supersedes"."newer" IS 'The replacing parameterisation.';
COMMENT ON COLUMN "tk"."supersedes"."older" IS 'The replaced parameterisation.';

CREATE TABLE "tk"."system_conserves" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "quantity" uuid NOT NULL,
    CONSTRAINT "system_conserves__pk" PRIMARY KEY ("system", "quantity"),
    CONSTRAINT "system_conserves__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."system_conserves" IS 'A conserved quantity a chemical system declares.';
COMMENT ON COLUMN "tk"."system_conserves"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."system_conserves"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."system_conserves"."quantity" IS 'A conserved quantity.';

CREATE TABLE "tk"."system_member" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "form" uuid NOT NULL,
    "role" "meta"."system_role" NOT NULL,
    "member_role" uuid,
    CONSTRAINT "system_member__pk" PRIMARY KEY ("system", "form"),
    CONSTRAINT "system_member__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."system_member" IS 'A species form that belongs to a chemical system, with its role there.';
COMMENT ON COLUMN "tk"."system_member"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."system_member"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."system_member"."form" IS 'A member.';
COMMENT ON COLUMN "tk"."system_member"."role" IS 'Its role in this system.';
COMMENT ON COLUMN "tk"."system_member"."member_role" IS 'The part it plays in the phases of this system, where the source states one.';

CREATE TABLE "tk"."system_reaction" (
    "id" uuid NOT NULL,
    "system" uuid NOT NULL,
    "reaction" uuid NOT NULL,
    "defines" uuid,
    CONSTRAINT "system_reaction__pk" PRIMARY KEY ("system", "reaction"),
    CONSTRAINT "system_reaction__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."system_reaction" IS 'A reaction that belongs to a chemical system.';
COMMENT ON COLUMN "tk"."system_reaction"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."system_reaction"."system" IS 'The system.';
COMMENT ON COLUMN "tk"."system_reaction"."reaction" IS 'A reaction of the system.';
COMMENT ON COLUMN "tk"."system_reaction"."defines" IS 'The secondary species form this reaction defines from the basis, when it is a defining reaction.';

CREATE TABLE "tk"."validity_coverage" (
    "id" uuid NOT NULL,
    "record" uuid NOT NULL,
    "kind" "meta"."envelope_kind" NOT NULL,
    "value" "meta"."validity_coverage_state" NOT NULL,
    CONSTRAINT "validity_coverage__pk" PRIMARY KEY ("record", "kind"),
    CONSTRAINT "validity_coverage__uq__id" UNIQUE ("id")
);
COMMENT ON TABLE "tk"."validity_coverage" IS 'Whether a source states regions of one kind for a record. No row means the record''s validity has not been mapped; a row with `not_stated` records that the source gives no such region.';
COMMENT ON COLUMN "tk"."validity_coverage"."id" IS 'Deterministic identifier of the row, computed from its keys.';
COMMENT ON COLUMN "tk"."validity_coverage"."record" IS 'The record.';
COMMENT ON COLUMN "tk"."validity_coverage"."kind" IS 'The kind of region.';
COMMENT ON COLUMN "tk"."validity_coverage"."value" IS 'Whether regions of this kind are stated.';

CREATE TABLE "param"."helmholtz_pure_fluid__pure__planck_einstein" (
    "set_id" uuid NOT NULL,
    "k" bigint NOT NULL,
    "n" "meta"."scalar" NOT NULL,
    "theta" "meta"."scalar" NOT NULL,
    CONSTRAINT "helmholtz_pure_fluid__pure__planck_einstein__ck__k__minimum" CHECK ("k" >= 1),
    CONSTRAINT "helmholtz_pure_fluid__pure__planck_einstein__pk" PRIMARY KEY ("set_id", "k")
);
COMMENT ON TABLE "param"."helmholtz_pure_fluid__pure__planck_einstein" IS 'One Planck-Einstein term of the ideal-gas part.';
COMMENT ON COLUMN "param"."helmholtz_pure_fluid__pure__planck_einstein"."set_id" IS 'The parameter set this row belongs to.';
COMMENT ON COLUMN "param"."helmholtz_pure_fluid__pure__planck_einstein"."k" IS 'Term number.';
COMMENT ON COLUMN "param"."helmholtz_pure_fluid__pure__planck_einstein"."n" IS 'Coefficient.';
COMMENT ON COLUMN "param"."helmholtz_pure_fluid__pure__planck_einstein"."theta" IS 'Characteristic temperature over the reducing temperature.';

CREATE TABLE "param"."helmholtz_pure_fluid__pure__power" (
    "set_id" uuid NOT NULL,
    "k" bigint NOT NULL,
    "n" "meta"."scalar" NOT NULL,
    "d" "meta"."scalar" NOT NULL,
    "t" "meta"."scalar" NOT NULL,
    CONSTRAINT "helmholtz_pure_fluid__pure__power__ck__k__minimum" CHECK ("k" >= 1),
    CONSTRAINT "helmholtz_pure_fluid__pure__power__pk" PRIMARY KEY ("set_id", "k")
);
COMMENT ON TABLE "param"."helmholtz_pure_fluid__pure__power" IS 'One polynomial term of the residual part.';
